def _asked_untracked_transfer_field(message_lower: str) -> Optional[str]:
    """The transfer-detail extract column a pointed question is about, when it
    is one the ORM projection drops. None otherwise."""
    for key, _label, cues in _UNTRACKED_TRANSFER_FIELDS:
        if any(c in message_lower for c in cues):
            return key
    return None


def _asked_registration_detail(message_lower: str) -> Optional[str]:
    """'place' / 'date' / 'reason' when the question is about where or when the
    deed was registered, or why the parcel was transferred. None otherwise.

    Runs as a pre-empt: without it "where was the deed registered?" is claimed
    by sale_deed_check (which answers "yes it is registered") and "when was it
    registered?" by the field map (which answers the *submission* date)."""
    m = message_lower
    if ("regist" in m or "registered" in m) and any(
            w in m for w in ("document number", "document no", "doc number",
                             "document_number", "ஆவண எண்")):
        return "docnum"
    _reg = ("regist" in m or "deed" in m or "பதிவு" in m or "பத்திர" in m
            or "register pann" in m or "registaar" in m)
    if _reg and any(w in m for w in (
            "where", "place", "which office", "which sub", "sub-registrar office",
            "sub registrar office", "sro office", "registered at",
            "registration place", "registration office",
            "எங்கு", "எந்த அலுவலக", "இடம்", "அலுவலக",
            "enga", "enga", "enge", "yenga")):
        return "place"
    if _reg and any(w in m for w in (
            "when", "what date", "which date", "date of registration",
            "registration date", "registered on", "எப்போது", "எந்த தேதி", "தேதி",
            "eppo", "eppothu", "eppadi date")):
        return "date"
    _tr = "transfer" in m or "mutat" in m or "மாற்ற" in m or "transferred" in m
    if _tr and any(p in m for p in (
            "why was", "why is", "why it was", "why this was", "why did",
            "reason for transfer", "reason for the transfer", "transfer reason",
            "mutation reason", "reason it was transferred", "why transferred",
            "transferred by", "transfer by", "transferred via", "transferred on",
            "yen ", "yaen ", "transfer aachu", "transfer aayiduchu",
            "ஏன் மாற்ற", "மாற்றக் காரணம்", "மாற்றத்திற்கான காரணம்")):
        return "reason"
    # A yes/no about the reason -- "is X a court order transfer?", "was it a
    # gift deed transfer?", "transferred by inheritance?"
    if _tr and _named_transfer_reason(m):
        return "reason"
    return None


# The reason phrases officers name, mapped to how transfer_reason reads in the
# extract. Longest / most specific first.
_NAMED_REASON_MAP = [
    ("court order", "Court Order /Judgement"), ("court judgement", "Court Order /Judgement"),
    ("court judgment", "Court Order /Judgement"), ("court decree", "Court Order /Judgement"),
    ("gift deed", "Gift deed"), ("gift settlement", "Gift deed"), ("by gift", "Gift deed"),
    ("settlement deed", "Settlement deed"), ("by settlement", "Settlement deed"),
    ("partition deed", "Partition deed"), ("by partition", "Partition deed"),
    ("release deed", "Release deed"), ("by release", "Release deed"),
    ("legal heir", "Legal Heir"), ("legal-heir", "Legal Heir"),
    ("inheritance", "Legal Heir"), ("inherited", "Legal Heir"),
    ("succession", "Legal Heir"), ("by will", "Legal Heir"),
    ("sale deed", "Sale deed"), ("by sale", "Sale deed"), ("through sale", "Sale deed"),
    ("purchase", "Sale deed"), ("purchased", "Sale deed"),
]


def _named_transfer_reason(message_lower: str) -> Optional[str]:
    """The transfer reason a yes/no question names, or None."""
    for cue, canon in _NAMED_REASON_MAP:
        if cue in message_lower:
            return canon
    return None


def _registration_detail_answer(detail: dict, kind: str, app_no: str,
                                is_tamil: bool, message: str = "") -> str:
    """Where / when the deed was registered, or why the parcel was transferred,
    from get_application_detail()'s projected patta-transfer fields."""
    place = detail.get("registration_place")
    date = detail.get("registration_date")
    reason = detail.get("transfer_reason") or detail.get("declared_reason")
    deed = detail.get("sale_deed_number")
    # A file with no completed transfer has not been "transferred" -- it was
    # FILED as a mutation of that kind. Only patta_transfers.transfer_reason
    # (not the application's declared_reason) means a transfer actually happened.
    _done = bool(detail.get("transfer_reason")) or (
        (detail.get("current_status") or detail.get("status")) in ("approved", "completed"))
    _v_en = "was transferred on" if _done else "was filed as a mutation of type"
    _v_ta = "மாற்றப்பட்டது —" if _done else "இந்த வகை மாற்றத்திற்காக தாக்கல் செய்யப்பட்டது —"
    if kind == "docnum":
        if not deed:
            return (f"விண்ணப்பம் {app_no}-க்கு பதிவு ஆவண எண் பதிவேட்டில் இல்லை."
                    if is_tamil else
                    f"No registration document number is recorded for application {app_no}.")
        return (f"விண்ணப்பம் {app_no}-ன் பதிவு ஆவண எண்: {deed}"
                f"{(' (' + place + ', ' + str(date) + ')') if (place and date) else ''}."
                if is_tamil else
                f"The registration document number for application {app_no} is {deed}"
                f"{(' (registered at ' + place + ' on ' + str(date) + ')') if (place and date) else ''}.")
    if kind == "place":
        if not place:
            return (f"விண்ணப்பம் {app_no}-க்கு பதிவு அலுவலகம் பதிவேட்டில் இல்லை."
                    if is_tamil else
                    f"No registration office is recorded for application {app_no}.")
        extra = (f", பதிவு ஆவணம் {deed}" if deed else "")
        return (f"விண்ணப்பம் {app_no}-ன் ஆவணம் {place}-இல் பதிவு செய்யப்பட்டது"
                f"{(' (' + str(date) + ')') if date else ''}{extra}." if is_tamil else
                f"The deed for application {app_no} was registered at {place}"
                f"{(' on ' + str(date)) if date else ''}"
                f"{(', document ' + deed) if deed else ''}.")
    if kind == "date":
        if not date:
            return (f"விண்ணப்பம் {app_no}-க்கு பதிவு தேதி பதிவேட்டில் இல்லை."
                    if is_tamil else
                    f"No registration date is recorded for application {app_no}.")
        return (f"விண்ணப்பம் {app_no}-ன் ஆவணம் {date} அன்று பதிவு செய்யப்பட்டது"
                f"{(' (' + place + ')') if place else ''}. "
                f"(இது சமர்ப்பித்த தேதி அல்ல.)" if is_tamil else
                f"The deed for application {app_no} was registered on {date}"
                f"{(' at ' + place) if place else ''}. "
                f"(This is the deed's registration date, not the filing date.)")
    # reason
    if not reason:
        return (f"விண்ணப்பம் {app_no}-க்கு மாற்றக் காரணம் பதிவேட்டில் இல்லை."
                if is_tamil else
                f"No transfer reason is recorded for application {app_no}.")
    named = _named_transfer_reason((message or "").lower())
    if named:
        # normalise Tamil transfer_reason values to their English label
        _rl = (reason or "").strip().lower()
        _matches = (named.lower() in _rl) or (
            _rl in ("விற்பனை ஆவணம்/ கிரைய ஆவணம்",) and named == "Sale deed") or (
            _rl in ("ஏற்பாடு/ செட்டில்மெண்டு ஆவணம்",) and named == "Settlement deed") or (
            _rl in ("விடுதலை ஆவணம்",) and named == "Release deed") or (
            _rl in ("தான ஆவணம்",) and named == "Gift deed") or (
            _rl in ("பாகப்பிரிவினை ஆவணம்",) and named == "Partition deed") or (
            _rl in ("வாரிசு உரிமை",) and named == "Legal Heir") or (
            _rl in ("நீதிமன்ற ஆணை",) and named == "Court Order /Judgement")
        if _matches:
            return (f"ஆம் — விண்ணப்பம் {app_no} {_v_ta} {reason}"
                    f"{(' (பதிவு ஆவணம் ' + deed + ')') if deed else ''}." if is_tamil else
                    f"Yes — application {app_no} {_v_en} {reason}"
                    f"{(' (registered deed ' + deed + ')') if deed else ''}.")
        return (f"இல்லை — விண்ணப்பம் {app_no} {_v_ta} {reason}, "
                f"நீங்கள் குறிப்பிட்டது அல்ல." if is_tamil else
                f"No — application {app_no} {_v_en} {reason}, "
                f"not what you named.")
    return (f"விண்ணப்பம் {app_no} {_v_ta} {reason}"
            f"{(' (பதிவு ஆவணம் ' + deed + ')') if deed else ''}." if is_tamil else
            f"Application {app_no} {_v_en} {reason}"
            f"{(' (registered deed ' + deed + ')') if deed else ''}.")


def _untracked_transfer_field_answer(app_no: str, field_key: str, is_tamil: bool) -> str:
    label = next(l for k, l, _c in _UNTRACKED_TRANSFER_FIELDS if k == field_key)
    ref = f" {app_no}" if app_no else ""
    if is_tamil:
        return (
            f"விண்ணப்பம்{ref}-ன் {label} உங்கள் SIS பதிவேட்டில் எடுக்கப்படவில்லை. அது "
            f"மூல பதிவு/மாற்ற விவர அடுக்கில் (nisd_/sub_div_patta_transfer_urban / "
            f"{field_key}) மட்டுமே உள்ளது — இந்த உதவியாளர் அதை வினவுவதில்லை, மேலும் "
            f"அந்த நெடுவரிசை பெரும்பாலான வரிசைகளில் காலியாகவே உள்ளது. மாற்றத்திற்கு "
            f"என்னால் தர முடிந்தவை: மாற்றக் காரணம், பதிவு இடம் மற்றும் தேதி, பதிவு "
            f"ஆவண எண், பழைய/புதிய பட்டா எண், மாற்ற ஆணை எண்/தேதி/குறிப்பு, SIS "
            f"பரிந்துரை மற்றும் குறிப்புகள்.")
    return (
        f"The {label} for application{ref} is not carried in your SIS register. "
        f"It exists only in the source registration/transfer detail extract "
        f"(nisd_/sub_div_patta_transfer_urban / {field_key}), which this assistant "
        f"does not query — and that column is blank on most rows there too. For "
        f"a transfer I can give you: the transfer reason, the registration place "
        f"and date, the registered deed number, the old / new patta number, the "
        f"transfer order number / date / remarks, and the SIS's own "
        f"recommendation and remarks.")


# The register stores parcel area only in square metres. When the officer asks
# for hectares / ares / acres (all three are columns of the source extract),
# the field map matched the bare word "area" and answered the sq.m figure with
# an "Area (sq.m)" label -- the wrong unit, presented as if it were the answer.
# Convert deterministically instead and show the working.
_AREA_UNIT_CUES = (
    ("hectare", ("hectare", "hectares", " ha ", " ha?", "hect", "ஹெக்டேர்", "எக்டேர்")),
    ("acre", ("acre", "acres", "ஏக்கர்")),
    ("ares", ("ares", "in are", "in ares", "ஆர்")),
)
_AREA_UNIT_DIVISOR = {"hectare": 10000.0, "ares": 100.0, "acre": 4046.856}
_AREA_UNIT_NAME = {"hectare": ("hectares", "ஹெக்டேர்"),
                   "ares": ("ares", "ஆர்"), "acre": ("acres", "ஏக்கர்")}


def _asked_area_in_unit(message_lower: str) -> Optional[str]:
    if not any(w in message_lower for w in (
            "area", "extent", "பரப்பு", "பரப்பளவு", "விஸ்தீரண")):
        return None
    for unit, cues in _AREA_UNIT_CUES:
        if any(c in message_lower for c in cues):
            return unit
    return None


def _area_unit_answer(sd: dict, app_no: str, unit: str, is_tamil: bool) -> Optional[str]:
    sqm = sd.get("area_sqm") or sd.get("survey_total_area_sqm")
    if not sqm:
        return None
    try:
        sqm = float(sqm)
    except (TypeError, ValueError):
        return None
    val = sqm / _AREA_UNIT_DIVISOR[unit]
    en, ta = _AREA_UNIT_NAME[unit]
    if is_tamil:
        return (f"விண்ணப்பம் {app_no}-ன் பதிவு செய்யப்பட்ட பரப்பளவு {sqm:g} ச.மீ, "
                f"அதாவது ≈ {val:.4g} {ta}. (பதிவேட்டில் ச.மீ மட்டுமே உள்ளது; "
                f"{ta} மதிப்பு கணக்கிடப்பட்டது.)")
    return (f"{app_no}'s recorded area is {sqm:g} sq.m, i.e. ≈ {val:.4g} {en}. "
            f"(Only sq.m is stored in your register; the {en} value is derived.)")


def _missing_field_answer(sd: dict, app_no: str, field_key: str,
                          field_label: str, is_tamil: bool) -> str:
    """Why a field is empty, when the emptiness is a fact rather than a gap.

    "No igrs form 6 number information found" reads as a hole in the record.
    An IGRS Form 6 number is raised only where the Sub-Registrar's IGRS builds
    the mutation off a registered deed, so a CSC or citizen file has none by
    definition, and saying so answers the question instead of dodging it.
    """
    if field_key == "igrs_form6_number":
        channel = sd.get("submission_channel")
        route = {"CSC": "a CSC counter",
                 "citizen": "the citizen (a revenue camp)"}.get(channel)
        if is_tamil:
            base = (f"{app_no}-க்கு IGRS படிவம் 6 எண் இல்லை. "
                    f"சார்பதிவாளர் (IGRS) மூலம் வரும் விண்ணப்பங்களுக்கு மட்டுமே "
                    f"அந்த எண் உண்டு")
            return base + (f"; இந்த கோப்பு {route} வழியாக வந்தது." if route else ".")
        base = (f"{app_no} has no IGRS Form 6 number. Only an application "
                f"referred by the Sub-Registrar carries one -- it names the "
                f"registered deed the mutation was raised from")
        return base + (f", and this file came in through {route}." if route else ".")
    if is_tamil:
        return f"{app_no} க்கு {field_label} தகவல் இல்லை."
    return f"No {field_label.lower()} information found for {app_no}."


def _sub_division_numbers(app) -> tuple:
    """The (temporary, final) sub-division numbers of an application, rendered.

    The temporary number ("3/T1") is assigned while the file is in the workflow;
    the final one ("4") replaces it only when the sub-division is confirmed, so a
    still-open or rejected file has no final number to show.
    """
    temps, finals = [], []
    for sd in (getattr(app, "application_sub_divisions", None) or []):
        if sd.temporary_sub_division_no:
            temps.append(sd.temporary_sub_division_no)
        if sd.proposed_sub_division_no and sd.proposed_sub_division_no != sd.temporary_sub_division_no:
            finals.append(sd.proposed_sub_division_no)
    return (", ".join(temps) or "N/A", ", ".join(finals) or "Not assigned")


def _render_submission_channel_basis(sd: dict, is_tamil: bool) -> str:
    """Show the working behind `applications.submission_channel`.

    The channel is derived once, when `appl_log_urban` is projected, by
    `can_channel()` in backend/sample_db/identifiers.py, from two columns:
    `source_name` (a placeholder `-` means no operator account touched the file,
    so it is the Sub-Registrar's unattended IGRS referral; an operator / VLE code
    means someone keyed it in at a counter) and `camp_flag` (`P` on an attended
    row marks a special revenue camp, where the operator files for the citizen
    standing in front of them). Everything else attended is a CSC
    counter. The CAN's length names the counter that ISSUED the number, not the
    channel, so it is reported as a corroborating detail and never as the reason.
    """
    channel = sd.get("submission_channel")
    if channel not in ("CSC", "citizen", "sub_registrar"):
        return ""
    app_no = sd.get("application_number") or "N/A"
    src = sd.get("submission_source_name")
    can = sd.get("can_number")
    form6 = sd.get("igrs_form6_number")

    who = (src or "").strip()
    if is_tamil:
        head = {
            "CSC": f"விண்ணப்பம் {app_no} -- பொது சேவை மையம் (CSC) கோப்பு.",
            "citizen": f"விண்ணப்பம் {app_no} -- குடிமகனின் சொந்த சமர்ப்பிப்பு.",
            "sub_registrar": f"விண்ணப்பம் {app_no} -- சார்-பதிவாளர் (SRO) கோப்பு.",
        }[channel]
        if channel == "sub_registrar":
            body = ("இதை யாரும் உள்ளிடவில்லை; பதிவு செய்யப்பட்ட விற்பனைப் பத்திரத்திலிருந்து பதிவு அமைப்பே "
                    "அனுப்பியது."
                    + (f" அதன் பதிவு குறிப்பு எண் (IGRS படிவம் 6): {form6}." if form6 else ""))
        elif channel == "citizen":
            body = ("சிறப்பு வருவாய் முகாமில் தாக்கல் செய்யப்பட்டது: குடிமகன் முன்னால் நிற்க, ஆபரேட்டர்"
                    + (f" (குறியீடு {who})" if who else "") + " உள்ளிட்டார்; எனவே இது குடிமகனின் சொந்த சமர்ப்பிப்பு.")
        else:
            body = ("CSC கவுண்டரில் ஆபரேட்டர்" + (f" (குறியீடு {who})" if who else "")
                    + " குடிமகன் சார்பாக உள்ளிட்டார்; இது சிறப்பு வருவாய் முகாம் அல்ல.")
        out = [head, body]
        if can:
            out.append(f"CAN எண் {can} ({len(str(can))} இலக்கங்கள்) இதற்கு காரணம் அல்ல -- அது எண்ணை வழங்கிய "
                       "கவுண்டரை மட்டுமே காட்டும், கோப்பு வந்த வழியை அல்ல.")
        return "\n".join(out)

    head = {
        "CSC": f"CSC -- application {app_no} was entered at a Common Service Centre counter.",
        "citizen": f"Citizen -- application {app_no} is the citizen's own submission.",
        "sub_registrar": f"Sub-Registrar (SRO) -- application {app_no} came from the Sub-Registrar.",
    }[channel]
    if channel == "sub_registrar":
        body = ("Nobody typed it in: when the sale deed was registered, the registration system sent "
                "the transfer request to the survey office by itself."
                + (f" Its registration reference number (IGRS Form 6) is {form6}." if form6 else ""))
    elif channel == "citizen":
        body = ("It was filed at a special revenue camp: an operator" + (f" (code {who})" if who else "")
                + " keyed it in while the citizen stood in front of them, so it counts as the citizen's own "
                  "submission rather than a CSC counter's.")
    else:
        body = ("An operator" + (f" (code {who})" if who else "")
                + " at a CSC counter entered it on the citizen's behalf; it was not entered at a special "
                  "revenue camp.")
    out = [head, body]
    if can:
        out.append(f"Its CAN number ({can}, {len(str(can))} digits) is not the reason: the length only shows "
                   "which counter issued the number, not how the file arrived.")
    return "\n".join(out)


# ── Patta-transfer parties: "who is the new / previous owner of <app>?" ──────
# A patta transfer names two parties -- the transferor (previous owner) and the
# transferee (new owner) -- carried on patta_transfers.previous_owner /
# new_owner. Asking for either used to fall through to survey_owners, which
# dumps the WHOLE parcel's current co-owner register (100+ rows) and never
# looks at the word "new" or "previous". These answer the party the officer
# actually named, from get_application_detail()["transfer_parties"].
_TRANSFER_NEW_WORDS = ("new owner", "newowner", "transferee", "buyer", "purchaser",
                       "recipient", "person receiving", "புதிய உரிமையாளர்",
                       "பெறுநர்", "pudhiya urimaiyalar")
_TRANSFER_OLD_WORDS = ("previous owner", "prev owner", "old owner", "former owner",
                       "transferor", "seller", "vendor", "person transferring",
                       "பழைய உரிமையாளர்", "முந்தைய உரிமையாளர்", "வழங்குநர்",
                       "pazhaya urimaiyalar", "mundhaiya urimaiyalar")


def _asks_transfer_party(message: str) -> Optional[str]:
    """'new', 'previous', or None -- which side of a patta transfer the officer
    asked about."""
    m = (message or "").lower()
    if any(w in m for w in _TRANSFER_OLD_WORDS):
        return "previous"
    if any(w in m for w in _TRANSFER_NEW_WORDS):
        return "new"
    return None


def _transfer_party_answer(detail: dict, side: str, message: str,
                           is_tamil: bool) -> str:
    """Render the transferor or transferee of a patta-transfer application."""
    app_no = detail.get("application_id") or detail.get("application_number") or ""
    parties = detail.get("transfer_parties") or []
    label = ("முந்தைய உரிமையாளர் (வழங்குநர்)" if is_tamil else "previous owner (transferor)") \
        if side == "previous" else \
        ("புதிய உரிமையாளர் (பெறுநர்)" if is_tamil else "new owner (transferee)")
    key = "previous_owner" if side == "previous" else "new_owner"
    picked = [(p.get("sub_division_no"), p.get(key)) for p in parties if p.get(key)]
    if not picked:
        if is_tamil:
            return (f"விண்ணப்பம் {app_no}-க்கு பட்டா மாற்ற {label} பதிவு இல்லை. "
                    "இது பட்டா மாற்ற விண்ணப்பமாக இருந்தால் மட்டுமே இந்த விவரம் இருக்கும்.")
        return (f"No {label} is recorded for application {app_no}. "
                "This detail exists only once the file is projected as a patta transfer.")
    ml = (message or "").lower()
    want_aadhaar = any(w in ml for w in ("aadhaar", "aadhar", "adhaar", "ஆதார"))
    want_gender = any(w in ml for w in ("gender", "sex", "male", "female", "பாலின"))
    want_relative = any(w in ml for w in (
        "father", "relative", "husband", "wife", "spouse", "relationship",
        "தந்தை", "கணவ", "மனைவி", "உறவ"))
    lines = []
    for sd_no, o in picked:
        seg = o.get("name") or "N/A"
        extras = []
        if sd_no:
            extras.append((f"உட்பிரிவு {sd_no}" if is_tamil else f"sub-division {sd_no}"))
        if want_relative:
            rn = o.get("relative_name")
            extras.append((f"உறவினர்: {rn}" if is_tamil else f"relative: {rn}") if rn
                          else ("உறவினர் பெயர் SIS உரிமையாளர் பதிவில் இல்லை" if is_tamil
                                else "relative name not in the SIS owner register"))
        if want_aadhaar:
            a4 = o.get("aadhaar_last4")
            extras.append((f"ஆதார் முடிவு {a4}" if is_tamil else f"Aadhaar ending {a4}") if a4
                          else ("ஆதார் எண் பதிவில் இல்லை" if is_tamil
                                else "Aadhaar not on record"))
        if want_gender:
            g = o.get("gender")
            extras.append((f"பாலினம்: {g}" if is_tamil else f"gender: {g}") if g
                          else ("பாலினம் SIS உரிமையாளர் பதிவில் இல்லை" if is_tamil
                                else "gender not recorded in the SIS owner register"))
        if extras:
            seg += " (" + ", ".join(extras) + ")"
        lines.append(seg)
    body = "; ".join(lines)
    if is_tamil:
        ans = f"விண்ணப்பம் {app_no} — {label}: {body}."
    else:
        ans = f"Application {app_no} — {label}: {body}."
    # relationship / ownership share / extent / UDS / photo are not projected.
    if any(w in ml for w in ("ownership share", "share", "extent", "uds",
                             "undivided", "photo", "image", "பங்கு", "பரப்ப")):
        ans += ("\n\nஉரிமைப் பங்கு, பரப்பளவு, UDS விவரம், புகைப்படம் — இவை "
                "நகர்ப்புற natham-chitta / transfer-owner பிரிவில் மட்டுமே உள்ளன, "
                "SIS செயலியின் பதிவில் எடுக்கப்படவில்லை." if is_tamil else
                "\n\nOwnership share, extent, UDS details and photo are not carried "
                "in the projected SIS record for a transfer party -- they live only "
                "in the un-projected transfer-owner extract.")
    return ans


def _sis_recommendation_text(value: str, is_tamil: bool) -> str:
    """The SIS's own recommendation flag on a patta transfer -- "Y"/"N" in the
    extract -- rendered as words."""
    v = (value or "").strip().upper()
    if v in ("Y", "YES", "1", "T"):
        return "பரிந்துரைக்கப்பட்டது (Y)" if is_tamil else "Recommended (Y)"
    if v in ("N", "NO", "0", "F"):
        return "பரிந்துரைக்கப்படவில்லை (N)" if is_tamil else "Not recommended (N)"
    return value


def _render_submission_channel_answer(structured_data: dict, language: str,
                                      message: str = "") -> str:
    """Direct answer to "did this application come from a citizen or a CSC?".

    The channel is a stored fact, derived from appl_log_urban:
    `source_name = '-'` is the Sub-Registrar's unattended IGRS referral, an
    operator code with `camp_flag = 'P'` is a citizen filing at a special camp,
    and any other operator code is a CSC counter.
    """
    is_tamil = language in ("ta", "tanglish")
    if not structured_data or not structured_data.get("found", True):
        return (structured_data or {}).get(
            "message",
            "தயவுசெய்து விண்ணப்ப எண்ணை குறிப்பிடவும்." if is_tamil else
            "Please specify which application you're asking about. "
            "For example: 2026/0154/28/NNNNNN")

    app_no = structured_data.get("application_number") or "N/A"
    channel = structured_data.get("submission_channel")
    can = structured_data.get("can_number")
    form6 = structured_data.get("igrs_form6_number")

    # "why is it CSC?", "how do you know?", "explain in detail" -- the officer
    # is asking for the basis, not the label. Show the two columns the channel
    # was derived from instead of repeating the one-line verdict.
    if _CHANNEL_WHY_RE.search(message or ""):
        detailed = _render_submission_channel_basis(structured_data, is_tamil)
        if detailed:
            return detailed
    can_note = ""
    if can:
        can_note = (f" (CAN {can} — {len(str(can))} இலக்கங்கள்)" if is_tamil
                    else f" (CAN {can} — {len(str(can))} digits)")
    elif channel == "sub_registrar" and form6:
        # a referral with no CAN of its own -- the Form 6 number identifies it
        can_note = (f" (IGRS படிவம் 6 {form6})" if is_tamil
                    else f" (IGRS Form 6 {form6})")

    # "submitted through Sub-Registrar?" / "is this a CSC application?" name the
    # ONE channel being asked about -- a yes/no question, even though it carries
    # no "yes"/"no" word of its own. Answering with the true channel alone (what
    # the three branches below already did) reads as a description, not an
    # answer to the question asked -- the officer has to work out for themself
    # whether a channel that differs from the one named means "no". A bare
    # "how was this submitted?" / "which channel?" names no channel of its own
    # (extract_submission_channel returns None) and is left exactly as before.
    _asked_channels = extract_submission_channels(message or "")
    _asked_channel = _asked_channels[0] if _asked_channels else None
    _yn = ""
    if _asked_channel and not _CHANNEL_WHY_RE.search(message or ""):
        _match = _asked_channel == channel
        _yn = ("ஆம், " if _match else "இல்லை, ") if is_tamil else ("Yes — " if _match else "No — ")

    if channel == "CSC":
        return (f"{_yn}விண்ணப்பம் {app_no} பொது சேவை மையம் (CSC) மூலம் "
                f"சமர்ப்பிக்கப்பட்டது{can_note}." if is_tamil else
                f"{_yn}CSC — application {app_no} was submitted through a Common Service Centre{can_note}.")
    if channel == "citizen":
        return (f"{_yn}விண்ணப்பம் {app_no} குடிமகனால் நேரடியாக இணையதளத்தில் "
                f"சமர்ப்பிக்கப்பட்டது{can_note}." if is_tamil else
                f"{_yn}Citizen — application {app_no} was filed directly by the citizen "
                f"on the portal{can_note}.")
    if channel == "sub_registrar":
        return (f"{_yn}விண்ணப்பம் {app_no} துணை பதிவாளர் அலுவலகத்தின் பரிந்துரை மூலம் "
                f"வந்தது{can_note}." if is_tamil else
                f"{_yn}Sub-Registrar referral — application {app_no} reached the office "
                f"through the Sub-Registrar / IGRS Form 6 route{can_note}.")
    source = structured_data.get("source_name") or structured_data.get("source_code")
    if source:
        return (f"{_yn}விண்ணப்பம் {app_no}-இன் சமர்ப்பிப்பு மூலம்: {source}." if is_tamil
                else f"{_yn}Application {app_no} was submitted via: {source}.")
    return (f"விண்ணப்பம் {app_no}-க்கு சமர்ப்பிப்பு மூலம் பதிவு செய்யப்படவில்லை."
            if is_tamil else
            f"No submission channel is recorded against application {app_no}.")


_OWNER_FIELD_CUES = {
    "relative": ("father", "relative", "husband", "wife", "spouse", "parent",
                 "relationship", "தந்தை", "கணவ", "மனைவி", "பெற்றோர்", "உறவு",
                 "thanthai", "kanavan", "manaivi", "uravu"),
    "aadhaar": ("aadhaar", "aadhar", "ஆதார்", "ஆதார", "aathaar"),
    "gender": ("gender", "sex", "male", "female", "பாலின", "ஆண்", "பெண்",
               "paalinam", "aan", "pen"),
    "mobile": ("mobile", "phone", "contact number", "தொலைபேசி", "கைபேசி",
               "mobile number", "tholaipaesi"),
    "address": ("address", "residence", "door number", "முகவரி", "வீட்டு முகவரி",
                "mugavari"),
    "tamilname": ("in tamil", "tamil name", "தமிழில்", "தமிழ் பெயர்",
                  "tamil la", "tamil peru"),
    "englishname": ("in english", "english name", "name in english",
                    "in roman", "roman script", "romanized", "romanised",
                    "transliterate", "ஆங்கிலத்தில்", "ஆங்கிலத்தில",
                    "english la", "english peru"),
}


def _owner_wants(ml: str, key: str) -> bool:
    return any(w in ml for w in _OWNER_FIELD_CUES[key])


def _owner_detail_line(o: dict, message: str) -> str:
    """One `survey_owners` list line.

    The relative name / Aadhaar / gender / mobile / address are appended ONLY
    when the officer's question asked for that field -- every one is a column on
    the natham-chitta owner row (get_survey_owners._row). A bare "who is the
    father of the owner?" used to fall through to the LLM; a question about a
    field the extract leaves blank (mobile, address, and gender on most rows)
    now gets an explicit "not recorded" rather than a line that ignores it.
    """
    ml = (message or "").lower()
    name = o.get("name", "N/A")
    if _owner_wants(ml, "tamilname") and o.get("name_tamil"):
        name = o["name_tamil"]
    # Owner names are stored in Tamil script. Romanise inline only when the
    # officer explicitly asked for the English form -- a whole list annotated
    # with "(transliteration ~ ...)" on every line would be unreadable.
    elif _owner_wants(ml, "englishname") and isinstance(name, str):
        _rom = translit.tamil_to_latin(name)
        if _rom and _rom != name and translit.script_of(_rom) == "latin":
            name = _rom
    sub_div = o.get("sub_division", "Survey Level")
    share = o.get("ownership_share", "N/A")
    o_type = o.get("ownership_type", "Primary")
    line = f"  • {name} — Sub-division: {sub_div}, Share: {share}, Type: {o_type}"

    extras = []
    if _owner_wants(ml, "relative"):
        if o.get("relative_name"):
            _rel = o.get("relationship")
            extras.append(f"Relative: {_rel + ' ' if _rel else ''}{o['relative_name']}")
        else:
            extras.append("Relative: not recorded in the SIS owner register")
    if _owner_wants(ml, "aadhaar"):
        extras.append(f"Aadhaar ending {o['aadhaar_last4']}" if o.get("aadhaar_last4")
                      else "Aadhaar: not recorded in the SIS owner register")
    if _owner_wants(ml, "gender"):
        g = {"m": "Male", "f": "Female"}.get(str(o.get("gender") or "").lower(),
                                             o.get("gender"))
        extras.append(f"Gender: {g}" if g
                      else "Gender: not recorded in the SIS owner register")
    if _owner_wants(ml, "mobile"):
        extras.append(f"Mobile: {o['mobile']}" if o.get("mobile")
                      else "Mobile: not held for owners in the SIS register")
    if _owner_wants(ml, "address"):
        extras.append(f"Address: {o['address']}" if o.get("address")
                      else "Address: not held for owners in the SIS register")
    if extras:
        line += " — " + ", ".join(extras)
    return line


def _render_joint_owner_answer(sd: dict, language: str) -> str:
    """Human answer for the joint_owner_check intent from summarized data."""
    is_tamil = language in ("ta", "tanglish")
    survey_no = sd.get("survey_no", "N/A")
    app_no = sd.get("application_number")
    if is_tamil:
        prefix = (f"விண்ணப்பம் {app_no} (கணக்கெண் {survey_no})" if app_no
                  else f"கணக்கெண் {survey_no}")
    else:
        prefix = (f"For application {app_no} (Survey {survey_no})" if app_no
                  else f"For Survey {survey_no}")

    names = sd.get("joint_owner_names", [])
    groups = sd.get("joint_subdivisions", {})
    total_owners = sd.get("total_owners", 0)

    # Ambiguity note: a bare survey number that matched parcels in >1 ward.
    wards = sd.get("matched_wards", [])
    amb = ""
    if not app_no and sd.get("matched_parcels", 1) > 1 and len(wards) > 1:
        if is_tamil:
            amb = f" (கணக்கெண் {survey_no} பல வார்டுகளில் உள்ளது: {', '.join(wards)})"
        else:
            amb = f" (survey {survey_no} exists in multiple wards: {', '.join(wards)})"

    # The user named a sub-division that carries no ownership record; the list
    # below is the whole parcel's, so do not pass it off as that sub-division's.
    if sd.get("requested_sub_division") and sd.get("sub_division_found") is False:
        _req = sd.get("requested_sub_division")
        if is_tamil:
            amb += f" (உட்பிரிவு {_req}-க்கு தனி உரிமையாளர் பதிவு இல்லை; கணக்கெண் முழுவதும் காட்டப்படுகிறது)"
        else:
            amb += (f" (no ownership record is held against sub-division {_req}; "
                    f"the whole survey number is shown)")

    if total_owners == 0:
        return (f"{prefix}: உரிமையாளர் பதிவுகள் இல்லை.{amb}" if is_tamil
                else f"{prefix}: No ownership records found.{amb}")
    if not names:
        return (f"{prefix}: விண்ணப்பதாரர் ஒரே உரிமையாளர். கூட்டு உரிமையாளர்கள் இல்லை.{amb}"
                if is_tamil
                else f"{prefix}: The applicant is the sole owner. No joint owners are listed.{amb}")

    if is_tamil:
        head = (f"{prefix}: {len(names)} தனிப்பட்ட கூட்டு உரிமையாளர்கள், "
                f"{len(groups)} உட்பிரிவில்{amb}:")
    else:
        head = (f"{prefix}: {len(names)} distinct joint owner(s) across "
                f"{len(groups)} sub-division(s){amb}:")
    lines = [head]
    for sd_no, sd_names in groups.items():
        lines.append(f"  • {sd_no}: {', '.join(sd_names)}")
    return "\n".join(lines)


_WF_STAGE_LABEL = {
    "SIS": "Sub Inspector Surveyor",
    "SD": "Senior Draughtsman",
    "DIS": "Deputy Inspector Surveyor",
    "TAHSILDAR": "Zonal Level Tahsildar",
    "COMPLETED": "Completed",
    "REJECTED": "Rejected",
}


def _render_workflow_history(structured_data: dict, language: str) -> str:
    """Format the stage-by-stage workflow timeline (not just a count).

    Consumes the `history` list built for the application_status intent:
    each entry has from_stage / to_stage / changed_at / note / changed_by_name.
    """
    hist = structured_data.get("history", []) or []
    app_no = structured_data.get("application_number", "")
    is_tamil = language in ("ta", "tanglish")
    if not hist:
        return (f"விண்ணப்பம் {app_no}-க்கு பணிப்பாய்வு வரலாறு எதுவும் இல்லை."
                if is_tamil else
                f"No workflow history recorded for application {app_no}.")

    header = (f"விண்ணப்பம் {app_no} பணிப்பாய்வு வரலாறு ({len(hist)} படிகள்):"
              if is_tamil else
              f"Workflow history for {app_no} ({len(hist)} step(s)):")
    lines = [header]
    # Collapse consecutive hops that carry the same visible content (role
    # granularity is finer than stage granularity, so 44->42 and 42->41 both
    # read as SIS -> SIS).
    prev_key = None
    step = 0
    for h in hist:
        frm = h.get("from_stage")
        to = h.get("to_stage")
        when = (h.get("changed_at") or "")[:10]
        note = (h.get("note") or "").strip().strip("-").strip()
        who = h.get("changed_by_name") or ""
        key = (frm, to, note)
        if key == prev_key:
            continue
        prev_key = key
        step += 1
        frm_l = _WF_STAGE_LABEL.get(frm, frm) if frm else ("சமர்ப்பிப்பு" if is_tamil else "Submission")
        to_l = _WF_STAGE_LABEL.get(to, to) if to else "?"
        seg = f"  {step}. {when} — {frm_l} → {to_l}"
        if who and who != "System":
            seg += f" · {who}"
        if note:
            seg += f' · "{note[:80]}"'
        lines.append(seg)
    return "\n".join(lines)


def _is_owner_photo_request(message: str) -> bool:
    if _igrs_owner_qa.IMAGE in _igrs_owner_qa.parse(message)["keys"] and re.search(
            r"\b(?:is|are)\s+there\b|\bavai?lable\b|\battached\b", message or "", re.IGNORECASE):
        return False  # "is an owner image available for this record": a field of the IGRS owner row
    m = (message or "").lower()
    # Word-boundary, not bare substring: "pic" (short for "picture") matched
    # inside "EPIC number" -- the voter-ID field -- and "owner" in the same
    # breath ("epic number OF THE OWNER") made every EPIC-number question
    # answer with the owner-photo refusal instead of the field it asked for.
    if not any(re.search(r'(?<![a-z0-9])' + re.escape(w) + r'(?![a-z0-9])', m)
               for w in _OWNER_PHOTO_MEDIA_WORDS):
        return False
    if any(p in m for p in ["owner photo", "owner image", "owner_photo", "owner_image",
                            "owner's photo", "owners photo", "photo of the owner",
                            "photo of owner", "image of the owner"]):
        return True
    return any(w in m for w in _OWNER_PHOTO_SUBJECT_WORDS)


def _owner_photo_reply(language: str, message: str) -> str:
    is_ta = language == "ta" or any(w in (message or "") for w in ["புகைப்படம்", "படம்", "உரிமையாளர்"])
    if is_ta:
        return (
            "உரிமையாளரின் புகைப்படத்தை (PNG அல்லது வேறு எந்த வடிவத்திலும்) இந்த உதவியாளரால் "
            "வழங்க முடியாது. TAMILNILAM நகர்ப்புற தரவிலிருந்து உருவாக்கப்பட்ட SIS பதிவுகளில் "
            "உரிமையாளர் புகைப்படம் / படம் சேமிக்கப்படவில்லை — மூல `owner_photo` / `owner_image` "
            "புலங்கள் அனைத்தும் `-` அல்லது காலியாக உள்ளன; எந்த PNG/JPG/base64 படமும் இல்லை.\n\n"
            "உரிமையாளர் குறித்து நான் தர முடிந்தவை: பெயர் (தமிழ்/ஆங்கிலம்), ஆதார் எண், CAN, "
            "பட்டா எண், உரிமைப் பங்கு, கூட்டு உரிமையாளர் நிலை, இணைக்கப்பட்ட சர்வே/விண்ணப்பம். "
            "ஆவணங்களுக்கு — பதிவேற்ற நிலை மற்றும் வகையை (எ.கா. Sale Deed, ஆதார்) மட்டுமே தர முடியும், "
            "கோப்புகளை அல்ல."
        )
    return (
        "I can't return an owner's photo as a PNG (or in any other format). The SIS "
        "records built from the TAMILNILAM urban extracts don't store any owner "
        "photograph — the source `owner_photo` / `owner_image` fields are placeholders "
        "(`-` or empty) and no PNG, JPG, or base64 image is held for any owner.\n\n"
        "What I *can* pull up for an owner: name (English & Tamil), Aadhaar number, "
        "CAN, patta number, ownership share, joint-owner status, and the linked "
        "survey number / application. For documents I can report the upload status "
        "and type (e.g. Sale Deed, Aadhaar scan) — but not the files themselves."
    )


# ── "What was my previous message?" ──────────────────────────────────────────
# Meta questions about the conversation itself. Left to the LLM these get
# answered wrongly — it echoes the question just asked instead of the turn
# before it — so they are answered directly from the chat history the client
# sent, which is the only reliable record of what was said.
_RECALL_SUBJECT_WORDS = [
    "message", "msg", "question", "asked", "ask", "said", "say", "typed",
    "wrote", "query", "prompt", "chat", "conversation", "convo", "talk",
    "talked", "discuss", "discussed", "told", "spoke",
    "செய்தி", "கேள்வி", "சொன்ன", "கேட்ட", "உரையாடல", "பேசிய",
]
_RECALL_QUALIFIER_WORDS = [
    "previous", "prev", "last", "earlier", "before", "above", "first",
    # "remember" / "recall" ask for the conversation itself even with no
    # previous/last/earlier alongside them -- "do you remember our chat" and
    # "can you recall our conversation" carry no other qualifier word.
    "remember", "recall", "recollect",
    "முந்தைய", "கடந்த", "முன்பு", "மேலே", "முதல்", "நினைவு",
]


# Data questions that merely contain a recall-ish word ("when was it updated
# lastly", "last field visit date") are about the applications, not about the
# conversation, so they must not be swallowed here.
_RECALL_DATA_WORDS = [
    "application", "app", "apps", "survey", "update", "updated", "updation",
    "status", "visit", "sketch", "document", "owner", "patta", "deed",
    # A field named alongside "the previous question" makes it a data question
    # about that application, not a question about the conversation: "what is
    # the CAN number of the previous question?" was answered with "Your
    # previous message was: ..." because none of these were listed.
    "can", "aadhaar", "mobile", "name", "address", "ward", "block", "fee",
    "amount", "channel", "date", "subdivision", "igrs", "reason", "stage",
    "district", "taluk", "town", "applicant", "area", "type", "serial",
    "service", "renewal", "camp", "charge",
    "விண்ணப்ப", "புல எண", "நிலை", "பெயர்", "வார்டு", "கட்டணம்",
    "மாவட்ட", "தாலுகா", "நகர", "விண்ணப்பதாரர்",
]

# "continue from where we left off" / "pick up where we left off" name no
# subject noun at all -- there is no "message" or "conversation" in the
# sentence, just an idiom for "resume the earlier session" -- so the
# qualifier+subject pair above never fires for it. Left unhandled, this fell
# to the LLM fallback with an EMPTY chat_history and it fabricated a prior
# conversation wholesale ("we were discussing survey numbers ... 1234, 5678,
# 9012, 3456") instead of saying it had nothing to resume. These phrases are
# self-sufficient recall signals and skip the qualifier/subject check, but
# still go through the same _RECALL_DATA_WORDS guard below.
_RECALL_CONTINUATION_PHRASES = [
    "where we left off", "left off", "pick up where", "picking up where",
    "carry on from", "resume our conversation", "resume from before",
    "resume where", "continue our conversation", "continue from before",
    "continue where we", "let\'s continue", "lets continue",
    "தொடர்ந்து பேசுவோம்", "நிறுத்திய இடத்திலிருந்து",
]


def _tokens(text: str) -> set:
    return set(re.findall(r"[a-z0-9]+|[\u0b80-\u0bff]+", text))


def _is_conversation_recall(message: str) -> bool:
    if _clear_info_topic(message):
        return False  # "will you remember anything if I clear the chat?" is about clearing
    m = (message or "").lower().strip()
    if not m or len(m.split()) > 12:
        return False
    # Whole-token matching only: "lastly" is not "last", "asking" is not "ask"
    # in the sense meant here, and substring matching mistook
    # "when it was updated lastly" for a question about the chat itself.
    toks = _tokens(m)

    def _hit(words):
        # Tamil agglutinates, so its stems stay substring matches; English is
        # matched whole-token.
        return any(
            (w in m) if not w.isascii() else (w in toks)
            for w in words
        )

    is_continuation = any(p in m for p in _RECALL_CONTINUATION_PHRASES)
    if not is_continuation:
        if not _hit(_RECALL_QUALIFIER_WORDS):
            return False
        if not _hit(_RECALL_SUBJECT_WORDS):
            return False
    # "status of my previous application" is about data, not the conversation.
    # "can" alone is the CAN-number signal ("what is the CAN number of the
    # previous question?"), but "can you recall our earlier conversation?"
    # uses the same word as the auxiliary verb -- strip "can you"/"can i"/
    # "can we" before checking so the auxiliary use never masquerades as a
    # CAN-number question.
    data_toks = _tokens(re.sub(r"\bcan\s+(you|i|we)\b", " ", m))
    if any((w in m) if not w.isascii() else (w in data_toks) for w in _RECALL_DATA_WORDS):
        return False
    return True


def _conversation_recall_reply(message: str, chat_history: list, language: str) -> str:
    """Answer a recall question from chat_history (client-sent, oldest first).

    The current message is NOT part of chat_history — the frontend snapshots the
    history before storing it — so the last user entry is genuinely the previous
    turn.
    """
    m = (message or "").lower()
    is_ta = language == "ta" or any(w in (message or "") for w in ["செய்தி", "கேள்வி", "சொன்ன"])
    about_assistant = any(w in m for w in ["you say", "you said", "your last", "your previous",
                                           "your reply", "your response", "you tell", "you told"])
    want_role = "assistant" if about_assistant else "user"

    texts = [
        (h.get("content") or "").strip()
        for h in (chat_history or [])
        if (h.get("role") or "user") == want_role and (h.get("content") or "").strip()
    ]
    # "first message" asks for the other end of the conversation.
    wants_first = "first" in m or "முதல்" in m
    if not texts:
        if is_ta:
            return "இந்த உரையாடலில் அதற்கு முந்தைய செய்தி எதுவும் இல்லை — இதுதான் முதல் செய்தி."
        return "There is no earlier message in this conversation — this is the first one."

    picked = texts[0] if wants_first else texts[-1]
    if len(picked) > 400:
        picked = picked[:400] + "…"

    if want_role == "assistant":
        if is_ta:
            return f'நான் முன்பு சொன்னது: "{picked}"'
        return f'My previous reply was: "{picked}"'
    if is_ta:
        return f'உங்கள் முந்தைய செய்தி: "{picked}"'
    label = "first" if wants_first else "previous"
    return f'Your {label} message was: "{picked}"'


# ── "Who am I?" — the officer's own identity ─────────────────────────────────
# The officer is authenticated: their name, designation, employee id and
# jurisdiction are all on the request. Letting this fall through to the LLM
# produced "You are a Sub Inspector Surveyor (SIS) officer of Tamil Nadu" —
# true of every user of the system and of nobody in particular. It is answered
# here from the officer's own record instead.
_IDENTITY_PATTERNS = [
    r"\bwho\s+am\s+i\b", r"\bwho\s+i\s+am\b", r"\bwhoami\b",
    r"\bwho\s+are\s+you\s+talking\s+to\b",
    r"\bmy\s+name\b", r"\bmy\s+full\s+name\b", r"\bname\s+of\s+mine\b",
    # Typo-tolerant: "muy name", "myu name", "mi name", "mu name"
    r"\b(?:muy|myu|mi|mu)\s+name\b",
    r"\bmy\s+(?:designation|post|posting|rank|title|position|role)\b",
    r"\bmy\s+(?:employee|emp|staff|officer)\s*(?:id|number|code)\b",
    # "my user id" / "my user_id" — officer asking for their own login ID
    r"\bmy\s+(?:user[_\s]*id|login[_\s]*id|login)\b",
    r"\b(?:muy|myu|mi|mu)\s+(?:user[_\s]*id|login[_\s]*id)\b",
    r"\bmy\s+(?:profile|details|detail|info|information|credentials|account)\b",
    r"\babout\s+me\b", r"\bmy\s+identity\b",
    r"\bwhich\s+officer\s+am\s+i\b", r"\bam\s+i\s+(?:a|an|the)\s+sis\b",
    r"\bwhat\s+am\s+i\b",
    # Tamil
    r"நான்\s*யார்", r"நான்\s*யாரு", r"என்\s*பெயர்", r"எனது\s*பெயர்",
    r"என்\s*பதவி", r"எனது\s*பதவி", r"என்\s*விவரம்", r"எனது\s*விவரங்கள்",
    # Tanglish
    r"\bnaan\s*yaar\b", r"\bnaan\s*yar\b", r"\bnaan\s*yaaru\b",
    r"\ben\s*peyar\b", r"\ben\s*per\b", r"\bennoda\s*per\b",
    r"\ben\s*padhavi\b", r"\ben\s*pathavi\b",
]
_IDENTITY_RE = re.compile("|".join(_IDENTITY_PATTERNS), re.IGNORECASE)
# "role id" is an application field, and a named application means the question
# is about that file's officer, not about the officer asking.
_IDENTITY_BLOCKERS = ["role id", "role_id", "roleid"]
# "user id" / "user_id" are blocked only when the officer does NOT pair them
# with "my" — a bare "what is the user id" is an application field question,
# but "my user_id" / "what is my user id" is an identity question.
_IDENTITY_USER_ID_TERMS = ["user id", "user_id", "userid"]

# ── Sensitive-query guard: password / secret requests ────────────────────────
# Never reveal passwords. This check fires before every other handler so it
# cannot be bypassed by creative phrasing.
_SENSITIVE_RE = re.compile(
    # Only block security/account secrets — NOT India's postal 'pincode'.
    # "pin code" by itself is ambiguous (postal code vs. account PIN);
    # block it only when paired with a possessive ("my") or financial context
    # (atm, bank, otp, account). A bare "pincode of applicant" must pass through.
    r"\b(?:password|passcode|passwd|pass\s*word|secret\s*key|login\s*password"
    r"|my\s*pass|credentials?\s*password"
    r"|(?:my|atm|bank|account|otp|debit|credit)\s*pin(?:\s*code)?)\b",
    re.IGNORECASE,
)


def _is_sensitive_query(message: str) -> bool:
    """True when the message asks for a password or secret — must be refused."""
    return bool(_SENSITIVE_RE.search((message or "").strip()))


# ── "What is today's date?" — the calendar date, not an application field ────
# There was no handler for this at all. "date" is one of `_field_keywords`'
# per-application field names, so "what is todays date" fell into the same
# lookup as "what is the submission date" -- answered from whatever
# application happened to be in view, dated in the past, and presented as if
# it were today. An officer asking the day of the week got back the
# submission date of a file they had looked at minutes earlier. Answered here,
# from the server's own clock, before any application-field lookup runs.
_TODAY_DATE_RE = re.compile(
    r"\btoday'?s?\s+date\b|\bcurrent\s+date\b|\bdate\s+today\b"
    r"|\bwhat(?:'s| is)\s+(?:the\s+)?date\s+today\b"
    r"|\bwhat\s+date\s+is\s+(?:it|today)\b"
    r"|இன்றைய\s*தேதி|இன்று\s*என்ன\s*தேதி|இன்று\s*தேதி\s*என்ன",
    re.IGNORECASE,
)


def _is_today_date_question(message: str) -> bool:
    m = (message or "").strip().lower()
    if not m or len(m.split()) > 10:
        return False
    return bool(_TODAY_DATE_RE.search(m))


def _today_date_answer(language: str) -> str:
    today = date.today()
    formatted = today.strftime("%d %B %Y")
    if language in ("ta", "tanglish"):
        return f"இன்றைய தேதி: {formatted} ({today.isoformat()})."
    return f"Today's date is {formatted} ({today.isoformat()})."


def _is_officer_identity_question(message: str) -> bool:
    m = (message or "").strip().lower()
    if not m or len(m.split()) > 10:
        return False
    if any(b in m for b in _IDENTITY_BLOCKERS):
        return False
    if _OPINION_RE.search(m):
        return False           # "what do you think about me" asks for an opinion, not who I am
    # Block "user id" / "user_id" only when NOT preceded by "my" (or "mu"/"muy"
    # typo variants) — a bare "user id" is an application field, but
    # "my user id" is the officer asking about their own login.
    _has_user_id = any(t in m for t in _IDENTITY_USER_ID_TERMS)
    if _has_user_id:
        # Only allow if the message pairs it with a first-person possessive
        if not re.search(r"\b(?:my|mu|muy|myu|mi)\s+user", m):
            return False
    if re.search(r"\d{4}/\d{3,4}/\d{1,3}/\d+", m):
        return False
    return bool(_IDENTITY_RE.search(m))


_DESIGNATION_LONG = {
    "SIS": "Sub Inspector Surveyor (SIS)",
    "SD": "Senior Draughtsman (SD)",
    "DIS": "Deputy Inspector Surveyor (DIS)",
    "TAHSILDAR": "Zonal Level Tahsildar (ZDT)",
}
def _format_jurisdiction_line(jur: dict) -> str:
    """"Ward 002 (Block 0015), Thoothukudi town — Thoothukudi taluk, ... district (28)"."""
    if not jur:
        return ""
    parts = []
    for town in jur.get("towns") or []:
        for ward in town.get("wards") or []:
            blocks = ", ".join(b["block_number"] for b in (ward.get("blocks") or [])
                               if b.get("block_number"))
            ward_txt = f"Ward {ward.get('ward_number')}"
            if blocks:
                ward_txt += f" (Block {blocks})"
            parts.append(ward_txt)
        if town.get("name"):
            parts.append(f"{town['name']} town")
    taluk = (jur.get("taluk") or {}).get("name")
    if taluk and taluk != "N/A":
        parts.append(f"{taluk} taluk")
    district = jur.get("district") or {}
    if district.get("name") and district["name"] != "N/A":
        d_txt = district["name"] + " district"
        if district.get("code") and district["code"] != "N/A":
            d_txt += f" ({district['code']})"
        parts.append(d_txt)
    return ", ".join(parts)


def _identity_facet(message: str) -> str:
    """Which part of themselves the officer asked about.

    "who am i" wants a name and a post, not a personnel file — answer the
    question asked and nothing else. Only an explicit "my profile" / "my
    details" opens the full card.
    """
    m = (message or "").lower()
    if any(w in m for w in ["profile", "details", "detail", "information", "info",
                            "credentials", "account", "விவரம்", "விவரங்கள்"]):
        return "profile"
    if any(w in m for w in ["employee id", "emp id", "employee number", "staff id",
                            "staff number", "officer id", "officer code", "emp no",
                            "பணியாளர் எண்"]):
        return "employee_id"
    # "my login id" / "my user id" → show the login email, not just the emp ID
    if any(w in m for w in ["user id", "user_id", "userid", "login id", "login"]):
        return "login_id"
    if any(w in m for w in ["designation", "post", "posting", "rank", "title",
                            "position", "role", "பதவி", "padhavi", "pathavi"]):
        return "designation"
    if any(w in m for w in ["name", "பெயர்", "peyar", "per", "peru"]):
        return "name"
    return "who"


async def _officer_identity_reply(db: AsyncSession, officer, language: str,
                                  facet: str = "who") -> str:
    """The officer's own identity, from their record — never from the LLM."""
    is_ta = language in ("ta", "tanglish")
    row = None
    try:
        row = (await db.execute(
            select(SISOfficer).where(SISOfficer.id == officer.officer_id)
        )).scalar_one_or_none()
    except Exception as ex:
        logger.warning(f"Identity lookup fell back to the token context: {ex}")

    name = (row.name if row and row.name else officer.name) or "—"
    name_ta = (row.name_tamil if row else None) or ""
    designation = (row.designation if row and row.designation
                   else officer.designation) or "Sub Inspector Surveyor"
    employee_id = (row.employee_id if row else None) or officer.employee_id or "—"
    stage = officer.officer_stage
    stage_long = _DESIGNATION_LONG.get(stage, designation)
    display = (f"{name_ta} ({name})" if name_ta else name) if is_ta else \
              (f"{name} ({name_ta})" if name_ta else name)

    if facet == "name":
        return (f"உங்கள் பெயர் **{display}**." if is_ta
                else f"You are **{display}**.")
    if facet == "designation":
        return (f"உங்கள் பதவி: **{stage_long}**." if is_ta
                else f"Your designation is **{stage_long}**.")
    if facet == "employee_id":
        return (f"உங்கள் பணியாளர் எண்: **{employee_id}**." if is_ta
                else f"Your employee ID is **{employee_id}**.")
    if facet == "login_id":
        # "my login id" / "my user id" — show the login email used to sign in.
        email = (row.email if row else None) or getattr(officer, "email", None) or "—"
        if is_ta:
            return (f"உங்கள் உள்நுழைவு ஐடி (Login ID) உங்கள் மின்னஞ்சல் ஆகும்: **{email}**.\n"
                    f"பணியாளர் எண்: **{employee_id}**.")
        return (f"Your login ID is your registered email: **{email}**.\n"
                f"Employee ID: **{employee_id}**.")

    if facet != "profile":
        # "Who am I?" — name and post, one line.
        return (f"நீங்கள் **{display}**, {stage_long}." if is_ta
                else f"You are **{display}**, {stage_long}.")

    # Only "my profile" / "my details" asks for the whole card.
    email = (row.email if row else None) or officer.email or "—"
    mobile = (row.mobile if row else None) or ""
    jur_line, open_count = "", None
    try:
        jur = (await _build_jurisdiction_summary(db, officer)).get("jurisdiction") or {}
        jur_line = _format_jurisdiction_line(jur)
        open_count = jur.get("active_applications")
    except Exception as ex:
        logger.warning(f"Identity jurisdiction lookup failed: {ex}")

    if is_ta:
        lines = [f"• **பெயர்**: {display}",
                 f"• **பதவி**: {stage_long}",
                 f"• **பணியாளர் எண்**: {employee_id}",
                 f"• **மின்னஞ்சல்**: {email}"]
        if mobile:
            lines.append(f"• **கைபேசி**: {mobile}")
        if jur_line:
            lines.append(f"• **அதிகார வரம்பு**: {jur_line}")
        if open_count is not None:
            lines.append(f"• **நிலுவை விண்ணப்பங்கள்**: {open_count}")
        return "உங்கள் விவரங்கள்:\n" + "\n".join(lines)

    lines = [f"• **Name**: {display}",
             f"• **Designation**: {stage_long}",
             f"• **Employee ID**: {employee_id}",
             f"• **Email**: {email}"]
    if mobile:
        lines.append(f"• **Mobile**: {mobile}")
    if jur_line:
        lines.append(f"• **Jurisdiction**: {jur_line}")
    if open_count is not None:
        lines.append(f"• **Open applications assigned to you**: {open_count}")
    return "Your profile:\n" + "\n".join(lines)


# ── Format follow-ups ("in table", "as bullets", "in short") ────────────────
# A bare "in table" names no subject: parse_intent lands on general_query and
# the LLM, having no idea which table is meant, asks the officer what they
# want. The subject is the answer already on screen, so the whole family of
# format follow-ups is handled here as pure presentation — the previous
# assistant turn is re-rendered, never re-fetched and never re-worded.
#
# Format key -> the words that ask for it. Longest match wins, so "bullet
# points" resolves to bullets rather than to points' own entry.
_REFORMAT_WORDS = {
    "table": [
        "table", "tabular", "grid",
        "அட்டவணை", "அட்டவணையாக", "அட்டவணையில்", "attavanai", "attavanaiyaaga",
    ],
    "numbered": [
        "numbered list", "numbered", "number list", "numbering", "steps",
        "step by step", "1 2 3", "எண்ணிட்ட", "ennitta",
    ],
    "bullets": [
        "bullet points", "bullet point", "bullets", "bullet",
        "list", "listed", "points", "point form", "point wise", "pointwise",
        "பட்டியல்", "பட்டியலாக", "puLLigal", "pattiyal", "pattiyalaaga",
    ],
    "prose": [
        "paragraph", "sentence", "sentences", "prose", "plain text",
        "plain english", "words", "one line", "single line", "oneline",
        "வாக்கியம்", "பத்தி", "vaakkiyam", "patthi",
    ],
    "short": [
        "short", "shorter", "brief", "briefly", "summary", "summarise",
        "summarize", "concise", "crisp", "tldr", "in a nutshell",
        "சுருக்கமாக", "surukkamaaga", "surukkama",
    ],
    "json": ["json", "json format", "key value", "key-value"],
}
# Words that may surround a format request without changing what it asks for.
_REFORMAT_FILLER = {
    "in", "as", "a", "an", "the", "into", "to", "of", "it", "this", "that",
    "them", "those", "these", "all", "same", "above", "previous", "last",
    "show", "me", "give", "put", "make", "convert", "display", "render",
    "rewrite", "write", "print", "reply", "answer", "response", "say", "tell",
    "please", "pls", "plz", "kindly", "again", "now", "only", "just", "can",
    "you", "could", "would", "form", "format", "formatted", "view", "layout",
    "style", "mode", "way", "and", "or", "with",
    "la", "la?", "podu", "kaattu", "kaatu", "kaamikka", "venum", "kudu",
    "ஆக", "இல்", "காட்டு", "போடு", "வேண்டும்", "கொடு",
}
# "list" and "points" also start real queries ("list pending applications"),
# so with no previous answer to reshape they must fall through to the normal
# pipeline instead of answering "nothing to reformat".
_AMBIGUOUS_REFORMATS = {"bullets", "short"}

_REFORMAT_ROW_PATTERNS = [
    # "• **Application Type**: ISD"  (the multi-field detail answer)
    re.compile(r"^\s*(?:[•\-\*]|\d+[.)])\s*\*\*(?P<label>[^*]+?)\*\*\s*[:：]\s*(?P<value>.*)$"),
    # "• Application Type: ISD"
    re.compile(r"^\s*(?:[•\-\*]|\d+[.)])\s*(?P<label>[^:：]{1,60}?)\s*[:：]\s*(?P<value>.*)$"),
    # "**Status**: pending" with no bullet
    re.compile(r"^\s*\*\*(?P<label>[^*]+?)\*\*\s*[:：]\s*(?P<value>.*)$"),
]
# "The Application Type for 2026/0154/28/001167 is: ISD" — single-field answer.
_REFORMAT_SENTENCE_RE = re.compile(
    r"^\s*(?:the\s+)?(?P<label>[A-Za-z][A-Za-z ()./]{1,40}?)\s+for\s+\S+\s+is\s*[:：]?\s*(?P<value>.+?)\.?\s*$",
    re.IGNORECASE,
)
_TAG_RE = re.compile(r"<[^>]+>")


def _detect_reformat_request(message: str) -> Optional[str]:
    """The format a bare follow-up asks for, or None if it is a real query.

    Everything outside the format word must be filler, so "pending
    applications in a table" stays a query and goes down the normal path.
    """
    m = (message or "").strip().lower().rstrip("?!.")
    if not m or len(m.split()) > 6:
        return None
    hits = [
        (word, fmt)
        for fmt, words in _REFORMAT_WORDS.items()
        for word in words
        if re.search(rf"(?<!\w){re.escape(word)}(?!\w)", m)
    ]
    if not hits:
        return None
    # Longest phrase wins: "bullet points" is bullets, not points.
    word, fmt = max(hits, key=lambda h: len(h[0]))
    leftover = m
    for w, _ in sorted(hits, key=lambda h: len(h[0]), reverse=True):
        leftover = leftover.replace(w, " ")
    if not all(tok in _REFORMAT_FILLER for tok in leftover.split()):
        return None
    return fmt


def _strip_tags(fragment: str) -> str:
    text = _TAG_RE.sub(" ", fragment or "")
    for entity, char in (("&amp;", "&"), ("&lt;", "<"), ("&gt;", ">"),
                         ("&quot;", '"'), ("&#39;", "'"), ("&nbsp;", " ")):
        text = text.replace(entity, char)
    return re.sub(r"\s+", " ", text).strip()


def _parse_previous_answer(prev: str) -> dict:
    """Previous answer -> {caption, headers, rows}. Empty rows means unusable.

    Handles the three shapes an answer actually arrives in: an HTML table from
    build_html_response, a bullet/numbered field list, and the single-field
    sentence. Rows are lists of cells so a multi-column listing survives the
    round trip.
    """
    caption, headers, rows = "", [], []
    if not prev:
        return {"caption": "", "headers": [], "rows": []}

    if "<table" in prev.lower():
        intro = re.search(r"<div[^>]*class=['\"]table-intro['\"][^>]*>(.*?)</div>",
                          prev, re.IGNORECASE | re.DOTALL)
        if intro:
            caption = _strip_tags(intro.group(1)).rstrip(":：").strip()
        table = re.search(r"<table.*?</table>", prev, re.IGNORECASE | re.DOTALL)
        body = table.group(0) if table else prev
        headers = [_strip_tags(c) for c in
                   re.findall(r"<th[^>]*>(.*?)</th>", body, re.IGNORECASE | re.DOTALL)]
        for tr in re.findall(r"<tr[^>]*>(.*?)</tr>", body, re.IGNORECASE | re.DOTALL):
            cells = [_strip_tags(c) for c in
                     re.findall(r"<td[^>]*>(.*?)</td>", tr, re.IGNORECASE | re.DOTALL)]
            if cells:
                rows.append(cells)
        return {"caption": caption, "headers": headers, "rows": rows}

    for raw_line in prev.splitlines():
        line = raw_line.strip()
        if not line:
            continue
        matched = False
        for pat in _REFORMAT_ROW_PATTERNS:
            mt = pat.match(line)
            if mt:
                rows.append([mt.group("label").strip(), mt.group("value").strip()])
                matched = True
                break
        if matched:
            continue
        if not rows and not caption:
            sent = _REFORMAT_SENTENCE_RE.match(line)
            if sent:
                rows.append([sent.group("label").strip().title(),
                             sent.group("value").strip()])
                continue
            # A trailing-colon line above the bullets is the answer's header.
            if line.endswith(":") or line.endswith("："):
                caption = line.rstrip(":：").strip()
    return {"caption": caption, "headers": headers, "rows": rows}


def _render_reformatted(parsed: dict, fmt: str, language: str) -> str:
    """Render a parsed previous answer in the requested format."""
    rows = parsed.get("rows") or []
    if not rows:
        return ""
    is_ta = language in ("ta", "tanglish")
    caption = parsed.get("caption") or ""
    headers = parsed.get("headers") or []
    pairs = [(r[0], r[1] if len(r) > 1 else "") for r in rows] if all(
        len(r) <= 2 for r in rows) else []

    def _cells(row):
        return [c if c not in (None, "") else "-" for c in row]

    if fmt == "table":
        from html import escape as _esc
        if headers:
            head = "".join(f"<th>{_esc(h)}</th>" for h in headers)
        else:
            head = (f"<th>{'விவரம்' if is_ta else 'Field'}</th>"
                    f"<th>{'மதிப்பு' if is_ta else 'Value'}</th>")
        width = max(len(headers), max(len(r) for r in rows))
        body = ""
        for row in rows:
            cells = _cells(row) + ["-"] * (width - len(row))
            first = f"<td><strong>{_esc(cells[0])}</strong></td>" if not headers else f"<td>{_esc(cells[0])}</td>"
            body += "<tr>" + first + "".join(f"<td>{_esc(c)}</td>" for c in cells[1:]) + "</tr>"
        intro = f"<div class='table-intro'>{_esc(caption)}</div>" if caption else ""
        return (intro + "<table class='data-table'><thead><tr>" + head
                + f"</tr></thead><tbody>{body}</tbody></table>")

    if fmt in ("bullets", "numbered"):
        lines = [f"{caption}:"] if caption else []
        for i, row in enumerate(rows, start=1):
            marker = f"{i}." if fmt == "numbered" else "•"
            cells = _cells(row)
            if pairs:
                lines.append(f"{marker} **{cells[0]}**: {cells[1] if len(cells) > 1 else '-'}")
            elif headers and len(headers) == len(cells):
                joined = ", ".join(f"{h}: {c}" for h, c in zip(headers, cells))
                lines.append(f"{marker} {joined}")
            else:
                lines.append(f"{marker} " + " | ".join(cells))
        return "\n".join(lines)

    if fmt == "json":
        import json as _json
        if pairs:
            payload = {re.sub(r"\W+", "_", l.strip().lower()).strip("_"): v
                       for l, v in pairs}
        else:
            keys = headers or [f"col_{i+1}" for i in range(max(len(r) for r in rows))]
            payload = [dict(zip(keys, _cells(r))) for r in rows]
        return "```json\n" + _json.dumps(payload, indent=2, ensure_ascii=False) + "\n```"

    if fmt == "short":
        parts = [f"{l}: {v or '-'}" for l, v in pairs] if pairs else \
                [" ".join(_cells(r)) for r in rows]
        head = f"{caption} — " if caption else ""
        return head + "; ".join(parts) + "."

    # prose
    if pairs:
        joiner = " மற்றும் " if is_ta else " and "
        clauses = [f"{l.lower()} is {v or 'not recorded'}" for l, v in pairs] if not is_ta \
            else [f"{l} {v or 'பதிவு இல்லை'}" for l, v in pairs]
        body = ", ".join(clauses[:-1])
        body = (body + joiner + clauses[-1]) if len(clauses) > 1 else clauses[0]
    else:
        body = "; ".join(" ".join(_cells(r)) for r in rows)
    lead = f"{caption}: " if caption else ""
    return f"{lead}{body}."


def _reformat_previous_answer(chat_history: list, fmt: str, language: str) -> str:
    """The previous assistant answer in `fmt`, or "" if it cannot be reshaped."""
    prev = _last_assistant_message(chat_history)
    rendered = _render_reformatted(_parse_previous_answer(prev), fmt, language)
    if rendered:
        return rendered
    # Nothing tabular/bulleted was found to reshape. If the previous answer
    # was already a single plain-prose line (no HTML table, no bullet/field
    # rows) and prose or a short form is what's being asked for, it already
    # IS that -- "summarise briefly" / "in a sentence" right after a one-line
    # service-code answer used to report "it wasn't a set of fields" instead
    # of just repeating the sentence it already was.
    if fmt in ("prose", "short") and prev and "<table" not in prev.lower():
        return prev.strip()
    return ""


_REFORMAT_NAMES = {
    "en": {"table": "a table", "bullets": "bullet points", "numbered": "a numbered list",
           "prose": "a sentence", "short": "a short form", "json": "JSON"},
    "ta": {"table": "அட்டவணையாக", "bullets": "புள்ளிகளாக", "numbered": "எண்ணிட்ட பட்டியலாக",
           "prose": "வாக்கியமாக", "short": "சுருக்கமாக", "json": "JSON ஆக"},
}


def _cannot_reformat_reply(fmt: str, language: str, had_previous: bool) -> str:
    is_ta = language in ("ta", "tanglish")
    name = _REFORMAT_NAMES["ta" if is_ta else "en"].get(fmt, fmt)
    if is_ta:
        if had_previous:
            return (f"என் கடைசி பதிலை {name} மாற்ற முடியவில்லை — அது தனித்தனி "
                    "விவரங்களாக இல்லை. எந்த விவரங்கள் வேண்டும் என்று கேளுங்கள், "
                    "அதை அப்படியே காட்டுகிறேன்.")
        return (f"{name} காட்ட முந்தைய பதில் எதுவும் இல்லை. "
                "முதலில் என்ன விவரம் வேண்டும் என்று கேளுங்கள்.")
    if had_previous:
        return (f"I can't reshape my last reply into {name} — it wasn't a set of "
                "fields. Ask me for the details you want and I'll show them "
                f"in {name}.")
    return (f"There is no previous answer to show as {name} yet. "
            f"Ask for the details you want and I'll present them in {name}.")


# ── Bare date-scope follow-ups ("last month") ────────────────────────────────
def _last_user_message(chat_history: list, skip_bare_scopes: bool = True) -> str:
    """
    The officer's previous question. The frontend snapshots chat_history BEFORE
    storing the current message, so the last user entry is the prior turn.

    Bare periods are skipped by default: in "…approved this week" → "last
    month" → "what about June?", the question being re-scoped each time is the
    first one, not the re-scope that preceded it.

    A contentless turn ("no", "ok", "thanks") is skipped too -- it answered no
    question of its own, so it must not become "the previous question" for
    whatever comes after it. Without this, "explain ISD" → "no" (declining the
    bot's own "ask for more detail?" prompt) → "explain more detailed" lost
    the ISD topic: the intervening "no" became the thing being re-explained.
    """
    for h in reversed(chat_history or []):
        if (h.get("role") or "user") != "user":
            continue
        content = (h.get("content") or "").strip()
        if not content:
            continue
        if skip_bare_scopes and is_bare_date_scope(content):
            continue
        if _contentless_message(content) is not None:
            continue
        return content
    return ""


def _last_subject_message(chat_history: list) -> str:
    """The last user message that names what it is about ("show applications",
    "how many field visits"); a bare "how many" between it and a period follow-up
    ("last month") must not become the question that period re-scopes."""
    for h in reversed(chat_history or []):
        if (h.get("role") or "user") != "user":
            continue
        content = (h.get("content") or "").strip()
        if content and not is_bare_date_scope(content) and _OWN_SUBJECT_RE.search(content):
            return content
    return _last_user_message(chat_history)


def _resolve_prev_intent(chat_history: list) -> Optional[str]:
    """
    Intent of the previous turn.

    The client sends back only role/content/language/timestamp, so there is no
    intent field to read (the `[intent:…]` marker below is honoured if a client
    ever supplies one). Re-parsing the previous user message is what actually
    recovers it, and parse_intent is pure string work — no DB, no LLM.
    """
    for h in reversed(chat_history or []):
        if (h.get("role") or "user") == "assistant":
            marker = re.search(r'\[intent:([\w_]+)\]', h.get("content") or "")
            if marker:
                return marker.group(1)
            if h.get("intent"):
                return h.get("intent")
            break
    prev_user = _last_user_message(chat_history)
    return parse_intent(prev_user) if prev_user else None


def _rescope_followup_message(message: str, chat_history: list) -> str:
    """
    Fold a bare period ("last month", "what about June?") back into the
    question it re-scopes.

    "how many applications did I approve this week" followed by "lastt month"
    becomes "how many applications did I approve last month", so the previous
    turn's status/type/geography filters survive the follow-up instead of the
    message being answered as a contentless general query.

    Returns `message` unchanged when it is not a bare date follow-up.
    """
    if not message or not is_bare_date_scope(message):
        return message
    prev_intent = _resolve_prev_intent(chat_history)
    if prev_intent not in DATE_SCOPED_INTENTS:
        _subject = _last_subject_message(chat_history)
        prev_intent = parse_intent(_subject) if _subject else None
        if prev_intent not in DATE_SCOPED_INTENTS:
            return message
    prev_question = strip_date_scope_phrases(_last_subject_message(chat_history))
    scope = extract_date_scope_fragment(message) or message.strip()
    if not prev_question:
        return message
    return f"{prev_question} {scope}"


async def _build_comparison(db, officer, message: str, is_tamil: bool = False) -> dict:
    """Fetch both sides of a comparison and settle the question that was asked."""
    from backend.services.postgres import get_application_detail, get_comparison
    from backend.services.rag import parse_comparison_query

    _CMP_WANTS_NEWER.set(bool(re.search(r"\b(?:newer|newest|latest|recent|later)\b|puthu|புதி|பின்னை", message or "", re.IGNORECASE)))
    spec = parse_comparison_query(message)
    if not spec:
        return {"found": False, "message": (
            "எதை ஒப்பிட வேண்டும் என்று சொல்லுங்கள் — இரண்டு விண்ணப்ப எண்கள், அல்லது இரண்டு வகை / நிலை / வழி / வார்டு "
            "(எ.கா. \"ISD vs NISD\")." if is_tamil else
            "Tell me the two things to compare -- two application numbers, or two types, statuses, channels or wards "
            "(for example \"ISD vs NISD\").")}

    if spec["kind"] != "applications":
        if spec["kind"] == "ward" and spec.get("sides"):
            from backend.services.postgres import _officer_ward_numbers
            held = {str(w).zfill(3) for w in await _officer_ward_numbers(db, officer)}
            outside = [w for w in spec["sides"] if str(w).zfill(3) not in held]
            if outside:
                # a count of zero would read as a fact about a ward the officer cannot see
                ours = ", ".join(sorted(held)) or "-"
                names = ", ".join(outside)
                return {"found": False, "message": (
                    f"வார்டு {names} உங்கள் அதிகார வரம்பிற்கு வெளியே உள்ளது; நீங்கள் பார்க்கக்கூடிய வார்டுகள்: {ours}."
                    if is_tamil else
                    f"Ward {names} is outside your assigned jurisdiction, so I cannot compare it. "
                    f"The wards you hold: {ours}.")}
        scope, note = _comparison_scope(message, spec, is_tamil)
        if scope:
            spec = {**spec, "scope": scope}
        data = await get_comparison(db, officer, spec)
        data.setdefault("kind", spec["kind"])
        if scope and data.get("found"):
            data["scope_note"] = note
        # A decision date exists only for ISD/NISD files (the register carries
        # none for the other service codes), so a duration answer covers those
        # two services. Say so, or "your 19 approved applications" reads as the
        # officer's whole approved set when it is 78.
        if data.get("found") and (data.get("kind") in ("average_duration", "superlative")
                                  or data.get("aspect") == "duration"):
            _dn = ("முடிவு தேதி ISD / NISD கோப்புகளுக்கு மட்டுமே பதிவாகிறது; மற்ற சேவை குறியீடுகள் இதில் சேர்க்கப்படவில்லை."
                   if is_tamil else
                   "Only ISD and NISD files carry a recorded decision date, so this covers those two "
                   "services; the other service codes in the register are not included.")
            data["scope_note"] = f"{data['scope_note']} {_dn}" if data.get("scope_note") else _dn
        return data

    async def _side(number: str) -> dict:
        detail = await get_application_detail(db, number, officer)
        if not detail or not detail.get("found"):
            return {"application_number": number, "found": False}
        days = None
        if detail.get("decision_date") and detail.get("submission_date"):
            try:
                days = (date.fromisoformat(detail["decision_date"])
                        - date.fromisoformat(detail["submission_date"])).days
            except ValueError:
                days = None
        return {
            "found": True,
            "application_number": detail.get("application_number", number),
            "type": detail.get("type"), "status": detail.get("status"),
            "submission_date": detail.get("submission_date"),
            "decision_date": detail.get("decision_date"),
            "days_to_decide": days,
            "survey_no": detail.get("survey_no"),
            "ward_number": detail.get("ward_number"),
            "submission_channel": detail.get("submission_channel"),
            "area_sqm": detail.get("area_sqm"),
            "fee_amount": detail.get("fee_amount"),
        }

    left, right = await _side(spec["left"]), await _side(spec["right"])
    missing = [s["application_number"] for s in (left, right) if not s.get("found")]
    if missing:
        if is_tamil:
            return {"found": False, "kind": "applications",
                    "message": (f"{' மற்றும் '.join(missing)} படிக்க முடியவில்லை -- "
                                f"எண்ணைச் சரிபார்க்கவும், அல்லது அது உங்கள் அதிகார "
                                f"வரம்பிற்கு வெளியே இருக்கலாம்.")}
        return {"found": False, "kind": "applications",
                "message": (f"I could not read {' and '.join(missing)} -- check the "
                            f"number, or it may be outside your jurisdiction.")}

    # The verdict: answer the question that was actually asked. Was
    # hardcoded English regardless of the officer's language -- a Tamil
    # "compare 2026/... and 2026/..." got an all-English verdict line under
    # an otherwise Tamil field table.
    verdict = None
    aspect = spec.get("aspect")
    _and = " மற்றும் " if is_tamil else " and "
    if aspect == "duration":
        if left["days_to_decide"] is None or right["days_to_decide"] is None:
            still_open = [s["application_number"] for s in (left, right)
                          if s["days_to_decide"] is None]
            if is_tamil:
                verdict = (f"{_and.join(still_open)} இன்னும் முடிவு செய்யப்படவில்லை, "
                           f"எனவே ஒப்பிட நேரம் இல்லை.")
            else:
                verdict = (f"{' and '.join(still_open)} has not been decided yet, so "
                           f"there is no time to compare against.")
        elif left["days_to_decide"] == right["days_to_decide"]:
            verdict = (f"இரண்டும் {left['days_to_decide']} நாட்கள் எடுத்தன." if is_tamil
                      else f"Both took {left['days_to_decide']} days.")
        else:
            slow = max(left, right, key=lambda s: s["days_to_decide"])
            fast = min(left, right, key=lambda s: s["days_to_decide"])
            if is_tamil:
                verdict = (f"**{slow['application_number']}** அதிக நேரம் எடுத்தது: "
                           f"{slow['days_to_decide']} நாட்கள், {fast['days_to_decide']} "
                           f"நாட்களுக்கு எதிராக -- வேறுபாடு "
                           f"{slow['days_to_decide'] - fast['days_to_decide']} நாட்கள்.")
            else:
                verdict = (f"**{slow['application_number']}** took longer: "
                           f"{slow['days_to_decide']} days against "
                           f"{fast['days_to_decide']}, a difference of "
                           f"{slow['days_to_decide'] - fast['days_to_decide']} days.")
    elif aspect == "age":
        if left["submission_date"] == right["submission_date"]:
            verdict = (f"இரண்டும் {left['submission_date']} அன்று சமர்ப்பிக்கப்பட்டன."
                      if is_tamil else
                      f"Both were filed on {left['submission_date']}.")
        else:
            older = min(left, right, key=lambda s: s["submission_date"])
            newer = max(left, right, key=lambda s: s["submission_date"])
            try:
                gap = (date.fromisoformat(newer["submission_date"])
                       - date.fromisoformat(older["submission_date"])).days
                gap_txt = (f", {gap} நாட்கள் முன்பு" if is_tamil else f", {gap} days earlier")
            except ValueError:
                gap_txt = ""
            if _CMP_WANTS_NEWER.get():           # "which is newer" names the newer one
                if is_tamil:
                    verdict = (f"**{newer['application_number']}** புதியது: "
                               f"{newer['submission_date']} அன்று சமர்ப்பிக்கப்பட்டது, "
                               f"{older['submission_date']}க்கு எதிராக{gap_txt.replace('முன்பு', 'பின்பு')}.")
                else:
                    verdict = (f"**{newer['application_number']}** is newer: filed "
                               f"{newer['submission_date']} against "
                               f"{older['submission_date']}{gap_txt.replace('earlier', 'later')}.")
            elif is_tamil:
                verdict = (f"**{older['application_number']}** பழையது: "
                           f"{older['submission_date']} அன்று சமர்ப்பிக்கப்பட்டது, "
                           f"{newer['submission_date']}க்கு எதிராக{gap_txt}.")
            else:
                verdict = (f"**{older['application_number']}** is older: filed "
                           f"{older['submission_date']} against "
                           f"{newer['submission_date']}{gap_txt}.")
    elif aspect in ("area", "fee"):
        key = "area_sqm" if aspect == "area" else "fee_amount"
        lv, rv = left.get(key), right.get(key)
        _aspect_ta = "பரப்பளவு" if aspect == "area" else "கட்டணம்"
        if lv is None or rv is None:
            verdict = (f"{_aspect_ta} இரண்டிலும் பதிவு செய்யப்படவில்லை, எனவே "
                      f"ஒப்பிட முடியாது." if is_tamil else
                      f"The {aspect} is not recorded on both, so they cannot be compared.")
        elif lv == rv:
            verdict = (f"{_aspect_ta}-ல் இரண்டும் சமம்: {lv}." if is_tamil else
                      f"Both are the same on {aspect}: {lv}.")
        else:
            bigger = max(left, right, key=lambda s: s[key])
            smaller = min(left, right, key=lambda s: s[key])
            if is_tamil:
                verdict = (f"**{bigger['application_number']}** {_aspect_ta}-ல் "
                           f"பெரியது: {bigger[key]}, {smaller[key]}க்கு எதிராக.")
            else:
                verdict = (f"**{bigger['application_number']}** is larger on {aspect}: "
                           f"{bigger[key]} against {smaller[key]}.")

    return {"found": True, "kind": "applications", "aspect": aspect,
            "left": left, "right": right, "verdict": verdict}


def _compare_label(kind: str, value: str, is_tamil: bool = False) -> str:
    """How a comparison side is named in the answer."""
    if is_tamil:
        if kind == "channel":
            return {"CSC": "CSC / சேவை மையம்", "sub_registrar": "சார்-பதிவாளர்",
                    "citizen": "குடிமகன்"}.get(value, value)
        if kind == "status":
            return {"approved": "அங்கீகரிக்கப்பட்டது", "rejected": "நிராகரிக்கப்பட்டது",
                    "pending": "நிலுவையில் உள்ளது", "in_progress": "செயல்பாட்டில் உள்ளது",
                    "escalated": "மேல்நிலைப்படுத்தப்பட்டது"}.get(value, value)
        if kind == "type":
            return {"ISD": "ISD", "NISD": "NISD"}.get(value, value)
        return value
    if kind == "ward":
        return value
    if kind == "channel":
        return {"CSC": "CSC", "sub_registrar": "Sub-Registrar",
                "citizen": "Citizen portal"}.get(value, value)
    if kind == "status":
        return {"in_progress": "in progress"}.get(value, value)
    return value


_CMP_WANTS_NEWER = contextvars.ContextVar("cmp_wants_newer", default=False)


def _comparison_scope(message: str, spec: dict, is_tamil: bool):
    """({status_in, status_out, channel_out, type_out}, sentence) for "ISD vs NISD but not
    rejected" / "ISD vs NISD approved only" -- the counts are taken over what was asked."""
    kind = spec.get("kind")
    ex = {k: set(v) for k, v in _neg_scope.parse(message)[0].items()}
    for k, v in (_neg_scope.EXCLUDE.get() or {}).items():   # taken out of the message earlier this turn
        if k in ("status", "type", "channel"):
            ex.setdefault(k, set()).update(v)
    sides = {str(x) for x in (spec.get("sides") or [])}
    scope, words = {}, []
    if kind != "status" and ex.get("status"):
        scope["status_out"] = sorted(ex["status"])
    if kind != "channel" and ex.get("channel"):
        scope["channel_out"] = sorted(ex["channel"])
    if kind != "type" and ex.get("type"):
        scope["type_out"] = sorted(ex["type"])
    if kind != "status" and not scope.get("status_out"):
        st = fctx.refinement(message).get("status")
        if st and st not in sides:
            scope["status_in"] = [st]
    if not scope:
        return None, ""
    lab = lambda k, v: _compare_label(k, v, is_tamil) if k != "type" else v
    if scope.get("status_in"):
        words.append(("மட்டும்: " if is_tamil else "") + ", ".join(lab("status", v) for v in scope["status_in"])
                     + ("" if is_tamil else " only"))
    out = ([lab("status", v) for v in scope.get("status_out", [])] + [lab("channel", v) for v in scope.get("channel_out", [])]
           + list(scope.get("type_out", [])))
    if out:
        words.append((", ".join(out) + " தவிர") if is_tamil else "excluding " + ", ".join(out))
    return scope, (("எண்ணப்பட்டவை — " if is_tamil else "Counted over: ") + "; ".join(words) + ".")


_EXCLUDED_CODE_RE = re.compile(
    r"\b(?:not|except|excluding|outside|other\s+than|apart\s+from|aren.t|isn.t|are\s+not|is\s+not)\b"
    r"[^.?!]{0,25}?\b(?:service\s*code\s*)?(0\d{3})\b", re.IGNORECASE)


def _excluded_service_code_filter(message: str) -> Optional[str]:
    """The one non-ISD/NISD service code a message NEGATES -- "applications
    that are not service code 0158", "except 0158", "outside 0158" -- so a
    listing can exclude it rather than (wrongly) include it. "Show
    applications that are not service code 0158." used to be answered with
    exactly 0158's own 20 applications -- the opposite of what was asked --
    because `_requested_service_code_filter` read the bare digits with no
    awareness of the negation in front of them."""
    from backend.utils.helpers import SIS_URBAN_SERVICES
    m = _EXCLUDED_CODE_RE.search(message or "")
    if not m:
        return None
    code = m.group(1)
    if code in SIS_URBAN_SERVICES and code not in ("0153", "0154"):
        return code
    return None


def _requested_service_code_filter(message: str) -> Optional[str]:
    """The one non-ISD/NISD service code named in a bare listing request --
    "F-Line applications", "show 0158 applications" -- so that request
    returns just those applications, not the whole 152-row everything-table.
    ISD/NISD are excluded: they already have their own dedicated intents and
    a two-value result here would be ambiguous anyway (the all-service-code
    register treats "ISD" as the type column, not a service-code filter).

    Never returns a code the message NEGATES ("applications that are not
    service code 0158") -- that is `_excluded_service_code_filter`'s job, and
    reading the bare digits here regardless of the "not" in front of them
    answered the negated question with exactly the one thing it asked to
    leave out.
    """
    from backend.utils.helpers import find_service_codes
    codes = find_service_codes(message)
    if len(codes) == 1 and codes[0] not in ("0153", "0154"):
        if codes[0] == _excluded_service_code_filter(message):
            return None
        return codes[0]
    return None


def _requested_channel_filter(message: str) -> Optional[str]:
    """The one submission channel named in a bare listing request -- "citizen
    applications", "CSC applications" -- across every service code, not just
    the officer's ISD/NISD queue. "my CSC applications" keeps the existing
    pending_applications channel routing, since `parse_intent`'s rule for
    this already excludes "my"; this helper only runs when that rule fired.
    """
    channels = extract_submission_channels(message)
    return channels[0] if len(channels) == 1 else None


def _requested_status_filter_for_register(message: str):
    """The status filter for `service_register_entries`, which only ever
    carries approved/pending/rejected (coarse Open/Completed), unlike
    `Application`'s full pending/in_progress/escalated/approved/rejected
    state machine. "show pending applications from citizen" used to be
    excluded from the all-service-code listing entirely (the channel-only
    routing rule in rag.py stood aside the moment the message named a
    status), so it fell to pending_applications, which only ever sees the
    ISD/NISD rows in `Application` -- hiding every F-Line (0178) row that
    is also pending on that same channel. in_progress/escalated collapse
    to "pending" here (this table cannot tell them apart); a request for
    every status (e.g. "all pending and approved and rejected") collapses
    to None -- no filter -- rather than a no-op list of all three.
    """
    named = _explicit_status_request(message.lower())
    if named is None:
        return None
    _REGISTER_STATUSES = {"pending", "approved", "rejected"}

    def _coarsen(s):
        return "pending" if s in ("in_progress", "escalated") else s

    if isinstance(named, list):
        mapped = []
        for s in named:
            c = _coarsen(s)
            if c not in mapped:
                mapped.append(c)
        if set(mapped) >= _REGISTER_STATUSES:
            return None
        return mapped
    return _coarsen(named)


_HOOK_APP = __import__("contextvars").ContextVar("_HOOK_APP", default=None)


_WF_CUE = re.compile(
    r"\bwork[\s-]?flow\b|\bmovement\b|\btrail\b|\bwho\s+(?:has|is\s+holding)\s+it\b|\bwhere\s+is\s+(?:it|this|the\s+file|the\s+application)\b|"
    r"\bcurrent(?:ly)?\s+(?:desk|stage|at|with)\b|\bwhich\s+desk\b|\bpending\s+with\b|பணிப்பாய்வு|இப்போது\s*(?:யாரிடம்|எங்கே)|"
    r"\bwo?rk\s*fl\w*\b|\bwhat\s+happen\w*\s+to\b|\bactio\w*\s+(?:was\s+|were\s+)?(?:taken|eduthanga)\b|\bwho\s+updat\w*\b|"
    r"\bmove[ds]?\s+from\b|\breach(?:ed|ing)?\s+(?:the\s+)?(?:completed?|completion|closed|final|last)\b|"
    r"\bis\s+it\s+(?:at\s+|in\s+)?(?:the\s+)?(?:completed?|closed|final)\s+stage\b|"
    r"வொர்க்ஃப்ளோ|ஆக்ஷன்|ஆக்சன்", re.IGNORECASE)

# "has it reached the completed stage?" / "did it reach completion?" / "is it
# at the final stage?" -- a yes/no against the register's own coarse `stage`
# (Open / Completed), not a request to see anything else. Without this it had
# no handler at all: `_WF_CUE` above did not recognise "reached", so the
# question never reached this module and fell through to the full 16-field
# details card instead of the one-line answer it asked for.
_STAGE_REACHED_RE = re.compile(
    r"\breach(?:ed|ing)?\s+(?:the\s+)?(?:completed?|completion|closed|final|last)\s*(?:stage)?\b|"
    r"\bis\s+it\s+(?:at\s+|in\s+)?(?:the\s+)?(?:completed?|closed|final)\s+stage\b",
    re.IGNORECASE)

# "current stage?" / "where is it" / "which desk" / "who has it" / "pending
# with" ask for the file's PRESENT position only -- `_WF_CUE` also matches
# "workflow history", "what happened to", "action taken" and "who updated",
# which ask for the step-by-step log instead. Both used to get the exact same
# full "Workflow history for X (N step(s)): ..." card: a bare "current
# stage?" answered, but not the question that was actually asked.
_WF_STAGE_ONLY_RE = re.compile(
    r"\bcurrent(?:ly)?\s+(?:desk|stage|at|with)\b|\bwhich\s+desk\b|\bwho\s+(?:has|is\s+holding)\s+it\b|"
    # a pronoun-less "current stage?" / "where is it" is rewritten by
    # `unheld_qa.where_is()` into the canonical "where is {app} in the
    # workflow" before this function ever sees it, so the pronoun forms below
    # (it/this/the file/the application) never actually arrive here -- the
    # app-number form must be matched too, or every rewritten stage-only
    # question falls through to the full workflow-history branch instead.
    r"\bwhere\s+is\s+(?:it|this|the\s+file|the\s+application|\S+\s+in\s+the\s+workflow)\b|"
    r"\bpending\s+with\b|இப்போது\s*(?:யாரிடம்|எங்கே)",
    re.IGNORECASE)


async def _other_code_workflow(db, officer, message, gate_app, chat_history, ta):
    """"workflow history of <0178 file>", "where is it": a file under another service code has no ISD / NISD detail
    card to fall back on, and the whole details card is not the workflow. Same shape as the ISD / NISD history --
    unless the message asks only for the current stage/position, which gets the short answer instead."""
    if not _WF_CUE.search(message or "") or len((message or "").split()) > 14:
        return None
    app = extract_application_number(message) or gate_app or _unheld_qa.context_app(chat_history)
    if not app or app.count("/") < 3 or app.split("/")[1] in ("0153", "0154"):
        return None
    reg = await get_applications_by_numbers(db, officer, [app], include_rejected=True)
    rows = (reg or {}).get("applications") or []
    if not rows:
        return None
    if _STAGE_REACHED_RE.search(message or ""):
        text = await _othercode_detail.stage_reached(app, rows[0], ta)
    elif _WF_STAGE_ONLY_RE.search(message or "") and not _wants_workflow_history(message):
        text = await _othercode_detail.current_stage(db, app, rows[0], ta)
    else:
        text = await _othercode_detail.workflow(db, app, rows[0], ta)
    if text:
        _HOOK_APP.set(app)
    return text


_DOCS_CUE = re.compile(r"\bdocu?\w*|\batta?c?h?ments?\b|ஆவண|டாக்குமெண்ட்", re.IGNORECASE)
_DOCS_SKIP = re.compile(r"\bmissing\b|\bmising\b|\bsd\b|\bsketch\b|\bdraughtsman\b|\.(?:pdf|csv|docx|txt)\b|\b(?:this|the|that|my)\s+(?:uploaded\s+)?file\b|"
                        r"\brequired\s+for\b|\bneeded\s+for\b|\bwhat\s+documents\s+(?:are|do)\b(?!.*\d{4}/)", re.IGNORECASE)


async def _attached_documents(db, officer, message, gate_app, chat_history, ta):
    """"what documents were uploaded for X", "list all attachments for X", "which documents are verified":
    read from the source attachment extract for any service code. Missing-document questions stay with the
    application-information record; a chat upload ("this file", "report.pdf") stays with attachment_qa."""
    m = message or ""
    if not _DOCS_CUE.search(m) or _DOCS_SKIP.search(m) or len(m.split()) > 16:
        return None
    app = extract_application_number(m) or gate_app or _unheld_qa.context_app(chat_history)
    if not app or app.count("/") < 3:
        return None
    reg = await get_applications_by_numbers(db, officer, [app], include_rejected=True)
    if not (reg or {}).get("applications"):
        return None              # not this officer's file: the jurisdiction refusal answers it
    _HOOK_APP.set(app)
    return await _othercode_detail.attachments(db, app, ta)


_SAME_IP_CUE = re.compile(r"\b(?:same|identical|matching)\s+(?:submission\s+)?ip\b|\bshare\s+(?:the\s+)?(?:same\s+)?(?:submission\s+)?ip\b", re.IGNORECASE)
_DIFF_IP_CUE = re.compile(r"\bdifferent\s+(?:submission\s+)?ip\b", re.IGNORECASE)


async def _ip_comparison_answer(db, officer, message, gate_app, chat_history, ta):
    """"which applications share the same submission IP as X?" / "...have a different submission
    IP from X?" -- a dedicated comparison, scoped to this officer's own jurisdiction throughout
    (the SQL query itself filters by jurisdiction; nothing is checked only in prose), always
    excluding the named application, always excluding rows with no recorded IP. Previously
    unhandled: no module claimed either phrasing, so "same submission IP" fell to an unrelated
    owner-record comparison (the generic "compare" wording matched there first) and "different
    submission IP" just echoed the named application's own IP back without ever listing others."""
    same = bool(_SAME_IP_CUE.search(message or ""))
    diff = bool(_DIFF_IP_CUE.search(message or ""))
    if not (same or diff) or len((message or "").split()) > 20:
        return None
    app = extract_application_number(message) or gate_app or _unheld_qa.context_app(chat_history)
    if not app or app.count("/") < 3:
        return None
    from backend.services.postgres import get_applications_by_submission_ip
    data = await get_applications_by_submission_ip(db, officer, app, same=same)
    if data is None:
        return None
    _HOOK_APP.set(app)
    if not data.get("ip"):
        return (f"{app}-க்கான சமர்ப்பிப்பு IP பதிவில் இல்லை, ஒப்பிட முடியவில்லை." if ta
                else f"No submission IP is recorded for {app}, so it cannot be compared.")
    rows = data["applications"]
    which = "same" if same else "different"
    which_ta = "அதே" if same else "வேறு"
    if not rows:
        return (f"{app} ({data['ip']}) தவிர வேறு எந்த விண்ணப்பமும் {which_ta} IP-ஐ பகிரவில்லை." if ta
                else f"No other application in your jurisdiction has {'the same' if same else 'a different'} "
                     f"submission IP as {app} ({data['ip']}).")
    nums = [r["application_number"] for r in rows]
    shown = nums[:15]
    tail = f" and {len(nums) - 15} more" if len(nums) > 15 else ""
    if ta:
        return f"{app} ({data['ip']}) உடன் {which_ta} IP பகிரும் {len(nums)} விண்ணப்பங்கள்: {', '.join(shown)}{tail}."
    return (f"{len(nums)} application(s) have {'the same' if same else 'a different'} submission IP "
            f"{'as' if same else 'from'} {app} ({data['ip']}): {', '.join(shown)}{tail}.")


_DECIDER_CUE = re.compile(r"\bwho\s+(?:approved|rejected|signed|decided|closed|cleared|sanctioned)\b|\bwho\s+(?:is|was)\s+(?:the\s+)?(?:approver|approving\s+officer)\b", re.IGNORECASE)


async def _who_decided(db, officer, message, gate_app, chat_history, ta):
    if not _DECIDER_CUE.search(message or "") or len((message or "").split()) > 12:
        return None
    app = extract_application_number(message) or gate_app or _unheld_qa.context_app(chat_history)
    if not app or app.count("/") < 3:
        return None
    reg = await get_applications_by_numbers(db, officer, [app], include_rejected=True)
    rows = (reg or {}).get("applications") or []
    if not rows:
        return None
    text = await _othercode_detail.decider(db, app, rows[0], ta)
    if text:
        _HOOK_APP.set(app)
    return text


async def _early_subdivision_answer(db, officer, message, intent, gate_app, chat_history, language):
    """The record answer as the card every other answer uses (see card_html)."""
    ta = language in ("ta", "tanglish")
    _wd = await _who_decided(db, officer, message, gate_app, chat_history, ta)
    if _wd:
        return _wd
    _ipc = await _ip_comparison_answer(db, officer, message, gate_app, chat_history, ta)
    if _ipc:
        return _ipc
    _wf = await _other_code_workflow(db, officer, message, gate_app, chat_history, ta)
    if _wf:
        return _wf              # plain lines: the shape of an ISD / NISD file's workflow history
    _docs = await _attached_documents(db, officer, message, gate_app, chat_history, ta)
    if _docs:
        return _docs
    _nh = _unheld_qa.answer_app(message, chat_history, ta)
    if _nh:
        _HOOK_APP.set(_nh[1])
        return _card_html.card(_nh[0], ta)
    out = await _early_subdivision_answer_inner(db, officer, message, intent, gate_app, chat_history, language)
    if isinstance(out, str) and out and (_negq.KIND.get() or _negq.HYP.get()):
        out = _negq.lead(_negq.shape(out, ta), ta)
    return _card_html.card(out, ta) if isinstance(out, str) else out


_ABSENT_RECORDS = (  # (message cue, English sentence, Tamil sentence): records a file of another service code cannot carry
    (r"igrs", "No IGRS owner record is held for {app}. IGRS owner rows exist only for NISD (0153) files referred by a Sub-Registrar.",
     "{app}-க்கு IGRS உரிமையாளர் பதிவு இல்லை. Sub-Registrar பரிந்துரைத்த NISD (0153) கோப்புகளுக்கு மட்டுமே அது உண்டு."),
    (r"returned\s+owner|return\s+owner", "No returned-owner record is held for {app} (the returned-owner table holds no records for any application at present).",
     "{app}-க்கு திருப்பப்பட்ட உரிமையாளர் பதிவு இல்லை (அந்த அட்டவணையில் தற்போது எந்த பதிவும் இல்லை)."),
    (r"new\s+owner", "No new-owner record is held for {app}. Only a full-field patta transfer (NISD, 0153) carries one.",
     "{app}-க்கு புதிய உரிமையாளர் பதிவு இல்லை. முழு புல பட்டா மாற்றத்துக்கு (NISD, 0153) மட்டுமே அது இருக்கும்."),
    (r"old\s+owner|chitta", "No old-owner record is held for {app}. An ISD file carries a chitta old-owner record and an NISD file a full-field old-owner record.",
     "{app}-க்கு பழைய உரிமையாளர் பதிவு இல்லை. ISD கோப்புக்கு சிட்டா பதிவும் NISD கோப்புக்கு முழு புல பதிவும் உண்டு."),
    (r"full[\s-]*field|zdt", "No full-field patta transfer record is held for {app}. Only an NISD (0153) file carries one.",
     "{app}-க்கு முழு புல பட்டா மாற்ற பதிவு இல்லை. NISD (0153) கோப்புக்கு மட்டுமே அது இருக்கும்."),
)


async def _other_code_absent(db, officer, message, app_no, detail, ta):
    """A file of another service code (0158 ...) lives in the register only: the owner / transfer records of
    an ISD or NISD file do not exist for it. Said plainly, after the officer's access is checked."""
    if app_no.count("/") < 3 or app_no.split("/")[1] in ("0153", "0154") or (detail and detail.get("found") is not False):
        return None
    if _um_parse(message) or _na_parse(message) or _cmflow_qa.parse(message) or _tslr_parse(message) or _fline_qa.parse(message)["keys"]:
        return None
    for cue, en, tam in _ABSENT_RECORDS:
        if re.search(cue, message, re.IGNORECASE):
            reg = await get_applications_by_numbers(db, officer, [app_no], include_rejected=True)
            if (reg or {}).get("applications"):
                return (tam if ta else en).format(app=app_no)
            return None
    return None


async def _early_subdivision_answer_inner(db, officer, message, intent, gate_app, chat_history, language):
    """The sub-division record answer, taken BEFORE the "not held in your register"
    guards. Those guards name tax rate, plot, soil and group numbers as absent
    even though the plot rows hold them; this answers first when the message asks
    for such a field about one application. The application is the one named in
    the message, else the one the gate confirmed or the conversation is about --
    and never when the message names a different survey number, or the intent
    is not an application lookup (a survey or listing question keeps its handler)."""
    _HOOK_APP.set(None)
    # A bare channel fragment ("application from sro", "applications from
    # csc") with no application number the officer has named -- same guard,
    # same reasoning, as `_cm_strong`'s: `_appinfo_qa.parse()` below reads
    # "sro" as the SRO-name FIELD of one record regardless of listing shape,
    # and this function is called unconditionally, ahead of and independent
    # of `_cm_strong` -- so fixing `_cm_strong` alone left this path still
    # resolving "application from sro" to the SRO field of whichever
    # application a prior LISTING happened to mention first, instead of
    # leaving it for the channel-scoped listing intent to answer.
    if (not extract_application_number(message) and extract_submission_channels(message) and (
            _qualifier_guard.listing_shaped(message)
            or (not _app_numbers_in_recent_context(chat_history, depth=6)[0] and len((message or "").split()) <= 10))):
        # A listing-shaped message ("what are applications from SRO?") is never a field
        # question about a stale application, even when the officer named one earlier in
        # the conversation -- the shape of THIS message settles it, the way `_cm_strong`'s
        # equivalent guard now also does. Without the `listing_shaped` escape, a prior
        # "<app> details" turn made every later channel-scoped listing resolve to that
        # one file's SRO/CSC/channel field instead of the register-wide listing.
        return None
    attrs = _subdivision_qa.attributes(message)
    _oo_attrs = _oldowner_qa.attributes(message) or _oo_exists_parse(message, chat_history)
    _cm_q = _cmflow_qa.parse(message)
    _ai_keys = _appinfo_qa.parse(message)
    _apk = _appinfo_qa.applicant_keys(message)
    _fl = _fline_qa.parse(message)
    _xc = _crosscheck_qa.parse(message)
    _ig = _igrs_owner_qa.parse(message) if _igrs_owner_qa.claims(message) else None
    _ig_strong = _igrs_owner_qa.claims_strong(message)
    _sdp = _sd_parse(message, chat_history)
    _tsl = _tslr_parse(message, chat_history)
    _um = _um_parse(message, chat_history)
    _na = _na_parse(message, chat_history)
    _ft = _fulltransfer_qa.parse(message) if _fulltransfer_qa.claims(message) else None
    _ft_strong = _fulltransfer_qa.claims_strong(message)
    _nw = _newowner_qa.parse(message) if _newowner_qa.claims(message) else None
    if _nw is None and _owner_ctx_compare(message, chat_history):
        _nw = _newowner_qa.parse("compare the new owner and the old owner " + message)
    _nw_strong = _newowner_qa.claims_strong(message)
    if _nw and _nw["kind"] == "uds_def":
        return _newowner_qa.UDS_TA if language in ("ta", "tanglish") else _newowner_qa.UDS_EN
    if not _subdivision_qa.claims(attrs) and not _oo_attrs and not _cm_q and not _ai_keys and not _apk and not _fl["keys"] and not _fl.get("fline") and not _xc and not _ig and not _nw and not _ft and not _sdp and not _tsl and not _um and not _na:
        return None
    named = extract_application_number(message)
    if not named:
        # a back-reference ("this / intha / இந்த") also claims a register-wide
        # listing, follow-up or survey intent: the officer points at the open application
        _backref = re.search(r"\b(?:this|it|its|intha|indha|idhu|idhoda|ithu)\b|இந்த|இதன்|இது",
                             message, re.IGNORECASE)
        if not _oo_attrs and not _cm_q and not _ai_keys and not _apk and not _fl["keys"] and not _xc and not _ig_strong and not _nw_strong and not _ft_strong and not _sdp and not _tsl and not _um and not _na and intent not in ("application_status", "general_query", "survey_detail", "survey_owners") and not (
                _backref and intent in ("all_service_code_applications", "followup_list")):
            return None
        if re.search(r"\bsurvey\s*(?:no\.?|number)?\s*\d|\bsy\.?\s*\d", message, re.IGNORECASE):
            return None
    # "what is TSLR?" / "what is an F-Line?" / "list TSLR applications" / "show
    # my SRO applications" -- a bare definition OR a register-wide listing,
    # never a question about whichever application chat_history last named.
    # `_fline_qa.parse()` / `_cmflow_qa.parse()` / `_tslr_parse()` /
    # `_appinfo_qa.parse()` / `.applicant_keys()` / ... all read the bare
    # record-type or field word alone as a truthy claim regardless of
    # listing shape (it genuinely might be a real per-application question,
    # "what is the F-Line verify date?"), so the claim itself cannot tell the
    # two apart -- only the app-number resolution below, where implicit
    # continuation would otherwise silently reattach the conversation's last
    # application, can. Gated to the same narrow concept list
    # `_is_bare_concept_definition` already uses (plus the listing shape), so
    # an ordinary field question ("what is the SIS recommendation?") still
    # resolves through chat_history as before.
    _bare_defn = (_is_bare_concept_definition(message) or _is_register_wide_listing(message)
                  or _is_ordinal_visit_reference(message))
    app_no = named or gate_app or (None if _bare_defn else _extract_app_number_from_context(
        message, chat_history, allow_implicit_continuation=True))
    if not app_no and not _bare_defn and (_oo_attrs or _cm_q or _ai_keys or _apk or _fl["keys"] or _xc or _ig or _nw or _ft or _sdp or _tsl or _um or _na):
        for _m in reversed(chat_history or []):
            _mm = _oldowner_qa._APP_NO.search((_m.get("content") if isinstance(_m, dict) else str(_m)) or "")
            if _mm:
                app_no = _mm.group(0)
                break
    if not app_no:
        return None
    _HOOK_APP.set(app_no)
    detail = await get_application_detail(db, app_no, officer=officer)
    _absent_txt = await _other_code_absent(db, officer, message, app_no, detail, language in ("ta", "tanglish"))
    if _absent_txt:
        return _absent_txt
    if _na:
        _okn = bool(detail and detail.get("found") is not False)
        _regn = None
        if app_no.count("/") >= 3:
            _gn = await get_applications_by_numbers(db, officer, [app_no], include_rejected=True)
            _gnl = (_gn or {}).get("applications") or []
            _okn = _okn or bool(_gnl)
            if _gnl:
                _regn = {"status": _gnl[0].get("status")}
        if _okn:
            _narows = await _natham_qa.load(db, app_no)
            _naoth = {}
            if _na["mode"] == "compare" and _narows is not None:
                _naoth = {"igrs": bool(await _igrs_owner_qa.load(db, app_no)), "chitta": bool((await _oldowner_qa.load(db, app_no))[0]),
                          "tslr": bool(await _tslr_qa.load(db, app_no)), "fullfield": bool(await _fulltransfer_qa.load(db, app_no)),
                          "new": bool(await _newowner_qa.load_new(db, app_no)), "old": bool(await _newowner_qa.load_old_nisd(db, app_no))}
            return _natham_qa.answer(_na, app_no, _narows, await _uamod_qa.load(db, app_no), _naoth, _regn, language in ("ta", "tanglish"))
    if _um and (_um.get("explicit") or (app_no.count("/") >= 3 and app_no.split("/")[1] in ("0158", "0159", "0160", "0162", "0164", "0169"))):
        _oku = bool(detail and detail.get("found") is not False)
        _regu = None
        if app_no.count("/") >= 3:
            _gu = await get_applications_by_numbers(db, officer, [app_no], include_rejected=True)
            _gul = (_gu or {}).get("applications") or []
            _oku = _oku or bool(_gul)
            if _gul:
                _regu = {"status": _gul[0].get("status")}
        if _oku:
            return _uamod_qa.answer(_um, app_no, await _uamod_qa.load(db, app_no), _regu, language in ("ta", "tanglish"))
    if _tsl:
        _okt = bool(detail and detail.get("found") is not False)
        _regt = None
        if app_no.count("/") >= 3:
            _gt = await get_applications_by_numbers(db, officer, [app_no], include_rejected=True)
            _gl = (_gt or {}).get("applications") or []
            _okt = _okt or bool(_gl)
            if _gl:
                _regt = {"survey_no": _gl[0].get("survey_no"), "subdivision_no": _gl[0].get("sub_division_no"),
                         "ward_number": _gl[0].get("ward_number"), "block_number": _gl[0].get("block_number")}
        if _okt:
            return _tslr_qa.answer(_tsl, app_no, await _tslr_qa.load(db, app_no), _regt, language in ("ta", "tanglish"))
    if _sdp and detail and detail.get("found") is not False:
        _sdrows = await _sdattach_qa.load(db, app_no)
        _sdsubs = (await _oldowner_qa.load(db, app_no))[1]
        _sdother = {"fline": bool(await _fline_qa.load(db, app_no)), "fullfield": bool(await _fulltransfer_qa.load(db, app_no)),
                    "survey_records": len(_sdsubs)}
        return await _sdattach_qa.answer(_sdp, app_no, _sdrows, detail, _sdsubs, _sdother, language in ("ta", "tanglish"))
    _ft_ok = bool(detail and detail.get("found") is not False)
    if _ft and not _ft_ok and app_no.count("/") >= 3:
        # the full-field transfer extract also carries 0165 files, which are not in `applications`:
        # access through the register, as every other record module does
        _ft_ok = bool(((await get_applications_by_numbers(db, officer, [app_no], include_rejected=True)) or {}).get("applications"))
    if _ft and _ft_ok:
        _ftrows = await _fulltransfer_qa.load(db, app_no)
        _ftta = language in ("ta", "tanglish")
        # "SIS recommendation" claims this module on vocabulary alone (SISREC is in its
        # DISTINCT set), but full_field_patta_transfer_urban only ever has a row for NISD
        # (0153) -- an ISD (0154) file has none, is expected to have none, and answering
        # "no full-field patta transfer record" explains the wrong table instead of this
        # file's OWN workflow_history, which may genuinely have the note being asked for.
        # Try the canonical workflow-history answer first and only fall through to the
        # full-field-transfer explanation when that returns nothing.
        if not _ftrows and app_no.count("/") >= 3 and app_no.split("/")[1] == "0154":
            _wftxt = await _workflow_history_answer(db, officer, message, app_no, _ftta)
            if _wftxt:
                return _wftxt
        # Same trap for an F-Line (0178) file: "transaction status" is vocabulary this
        # module shares with fline_qa's own TXN field, and full_field_patta_transfer_urban
        # never has a row for a 0178 file either. fline_qa actually has this field.
        if not _ftrows and app_no.count("/") >= 3 and app_no.split("/")[1] == "0178" and _fl["keys"]:
            _frow_ft = await _fline_qa.load(db, app_no)
            _fltxt = _fline_qa.answer(_fl["keys"], app_no, _frow_ft, _ftta)
            if _fltxt:
                return _fltxt
        if _ft["kind"] == "compare":
            if _ftrows or _ft_strong:
                _ftxt = _fulltransfer_qa.answer_compare(_ft, app_no, _ftrows, await _newowner_qa.load_new(db, app_no),
                                                        await _newowner_qa.load_old(db, app_no), (await _oldowner_qa.load(db, app_no))[1],
                                                        detail, _ftta)
                if _ftxt:
                    return _ftxt
        elif _ftrows or _ft["distinct"]:
            _ftxt = _fulltransfer_qa.answer(_ft["keys"], app_no, _ftrows, _ftta)
            if _ftxt:
                return _ftxt
    _nwrows = []
    if _nw and detail and detail.get("found") is not False:
        _nwrows = await _newowner_qa.load_new(db, app_no)
    _ig_rows_pre = await _igrs_owner_qa.load(db, app_no) if (_ig and detail and detail.get("found") is not False) else []
    if _nw and _nw["kind"] in ("return_field", "return_compare") and detail and detail.get("found") is not False:
        _rta = language in ("ta", "tanglish")
        _rrows = await _newowner_qa.load_return(db, app_no)
        _rtotal = await _newowner_qa.count_return(db) if not _rrows else len(_rrows)
        if _nw["kind"] == "return_compare":
            return _newowner_qa.answer_return_compare(_nw, app_no, _rrows, _rtotal, await _newowner_qa.load_new(db, app_no),
                                                      await _newowner_qa.load_old(db, app_no), await _igrs_owner_qa.load(db, app_no),
                                                      detail, _rta)
        return _newowner_qa.answer_return_fields(_nw["keys"], app_no, _rrows, _rtotal, await _appinfo_qa.load(db, app_no), detail, _rta)
    _nw_old_only = bool(_nw and _nw.get("old_only") and _nw["kind"] == "field")
    if _nw_old_only and detail and detail.get("found") is not False:
        # an OLD-owner field of a full-field (NISD) transfer; an ISD file's old owner is the chitta record,
        # answered further down by oldowner_qa
        _nold_rows = await _newowner_qa.load_old_nisd(db, app_no)
        if _nold_rows:
            return _newowner_qa.answer_fields(_nw["keys"], app_no, _nold_rows, language in ("ta", "tanglish"), old=True)
    if _nw and detail and detail.get("found") is not False and not (_ig and _ig["igrs"]) and not _ig_rows_pre             and (_nwrows or (_nw["kind"] in ("field", "compare") and not _nw_old_only)):
        _nta = language in ("ta", "tanglish")
        if _nw["kind"] == "compare":
            _nold = await _newowner_qa.load_old(db, app_no)
            _nig = await _igrs_owner_qa.load(db, app_no)
            _nfl = await _fline_qa.load(db, app_no)
            _nchit, _nsubs = await _oldowner_qa.load(db, app_no)
            _ntxt = await _newowner_qa.answer_compare(_nw, app_no, _nwrows, _nold, _nig, _nfl, _nsubs, detail, _nta)
        else:
            _ntxt = _newowner_qa.answer_fields(_nw["keys"], app_no, _nwrows, _nta)
        if _ntxt:
            return _ntxt
    if _ig and detail and detail.get("found") is not False:
        _igrows = _ig_rows_pre
        _igta = language in ("ta", "tanglish")
        if _ig["kind"] == "compare" and (_ig["igrs"] or _igrows):
            _igchitta, _ = await _oldowner_qa.load(db, app_no)
            _iginfo = await _appinfo_qa.load(db, app_no)
            return _igrs_owner_qa.answer_compare(_ig, app_no, _igrows, _igchitta, _iginfo, detail, _igta)
        if _igrows or _ig["igrs"] or (_igrs_owner_qa.IMAGE in _ig["keys"] and not _nwrows):
            return _igrs_owner_qa.answer_fields(_ig["keys"], app_no, _igrows, _igta)
    if _xc and detail and detail.get("found") is not False:
        _xinfo = await _appinfo_qa.load(db, app_no)
        _xown, _xsub = await _oldowner_qa.load(db, app_no)
        _xflow = await _cmflow_qa.load(db, app_no)
        _xtxt = await _crosscheck_qa.answer(_xc, message, app_no, db, officer, detail, _xinfo, _xown, _xsub, _xflow,
                                            language in ("ta", "tanglish"))
        if _xtxt:
            return _xtxt
    if (_fl["keys"] or _fl.get("fline")) and app_no.count("/") >= 3:
        _is_fl = app_no.split("/")[1] == "0178"
        if _is_fl or _fl.get("fline") or _fline_qa.claims(message):
            _okf = bool(detail and detail.get("found") is not False)
            if not _okf:
                _regf = await get_applications_by_numbers(db, officer, [app_no], include_rejected=True)
                _okf = bool((_regf or {}).get("applications"))
            if _okf:
                _frow = await _fline_qa.load(db, app_no) if _is_fl else None
                _ftxt = _fline_qa.answer(_fl["keys"], app_no, _frow, language in ("ta", "tanglish"))
                if _ftxt:
                    return _ftxt
    if not _ai_keys and _apk and app_no.count("/") >= 3 and app_no.split("/")[1] not in ("0153", "0154"):
        _ai_keys = _apk
    if _ai_keys:
        if detail and detail.get("found") is not False:
            _arow = await _appinfo_qa.load(db, app_no)
            if _arow is not None:
                return _appinfo_qa.answer(_ai_keys, app_no, _arow, detail, language in ("ta", "tanglish"))
        else:
            # a file under another service code: access is checked through the register, and
            # the record (an F-Line file has one) is read, never assumed absent
            _reg0 = await get_applications_by_numbers(db, officer, [app_no], include_rejected=True)
            _reg0l = (_reg0 or {}).get("applications") or []
            if _reg0l:
                _rd = {"status": _reg0l[0].get("status"), "submission_channel": _reg0l[0].get("submission_channel")}
                return _appinfo_qa.answer(_ai_keys, app_no, await _appinfo_qa.load(db, app_no), _rd,
                                          language in ("ta", "tanglish"))
    # "Tahsildar signature date" names the TAHSILDAR desk, which cmflow_qa.parse()
    # reads as a correction/modification recommendation question -- but that
    # table only ever covers 0158-0169, and an ISD/NISD file's real signature
    # date is patta_transfers.tahsildar_signature_date, a different record
    # entirely. Without this, cmflow_qa claimed it anyway and answered "no
    # correction/modification workflow record is held" for a file that was
    # never going to have one. See the matching guard in `_cm_strong`.
    if (_cm_q and app_no.count("/") >= 3 and app_no.split("/")[1] in ("0153", "0154")
            and re.search(r"\bsign\w*\s+date\b|\bdate\s+of\s+sign\w*\b", message or "", re.IGNORECASE)):
        _cm_q = None
    if _cm_q:
        _ok = bool(detail and detail.get("found") is not False)
        if not _ok:
            _reg = await get_applications_by_numbers(db, officer, [app_no], include_rejected=True)
            _ok = bool((_reg or {}).get("applications"))
        if _ok:
            _row = await _cmflow_qa.load(db, app_no)
            _svc = {"service_code": app_no.split("/")[1] if app_no.count("/") >= 3 else ""}
            if _row or not (_cm_q.desks == ["sis"] and not _cm_q.mode and not _cm_q.extra and detail
                            and detail.get("found") is not False):
                _txt = _cmflow_qa.answer(message, _cm_q, app_no, _row, _svc, language in ("ta", "tanglish"))
                if _txt:
                    return _txt
    if (_oo_attrs or _subdivision_qa.claims(attrs)) and not (detail and detail.get("found") is not False):
        # an application under another service code: no old-owner / sub-division plot rows to read
        _regx = await get_applications_by_numbers(db, officer, [app_no], include_rejected=True)
        if (_regx or {}).get("applications"):
            _ta = language in ("ta", "tanglish")
            _code = app_no.split("/")[1] if app_no.count("/") >= 3 else ""
            if _oo_attrs:
                _oo, _sub = await _oldowner_qa.load(db, app_no)
                return _oldowner_qa.answer(message, _oo_attrs, app_no, _oo, _sub, _ta)
            if not await _subdivision_qa.load_plots(db, app_no):
                return (f"விண்ணப்பம் {app_no} (சேவை {_code})-க்கு உட்பிரிவு மனை பதிவு இல்லை." if _ta else
                        f"No sub-division plot record is held for {app_no} (service code {_code}).")
    if _oo_attrs and detail and detail.get("found") is not False:
        _oo, _sub = await _oldowner_qa.load(db, app_no)
        return _oldowner_qa.answer(message, _oo_attrs, app_no, _oo, _sub, language in ("ta", "tanglish"))
    return await _subdivision_answer(db, officer, message, detail, app_no,
                                     language in ("ta", "tanglish"))


async def _subdivision_answer(db, officer, message: str, sd: dict, app_no: str, is_tamil: bool):
    """An answer about the sub-division plots of one application (temporary / new
    sub-division number, existing / new patta, area in hectare-ares-sq.m, land
    use, tax, soil, plot, group numbers, owners), or None when the message asks
    for none of them. `sd` is the application detail the caller already fetched
    under the officer's jurisdiction, so access has been checked before any plot
    row is read. See subdivision_qa."""
    attrs = _subdivision_qa.attributes(message)
    if not app_no or not sd or sd.get("found") is False or not _subdivision_qa.claims(attrs):
        return None
    plots = await _subdivision_qa.load_plots(db, app_no)
    owners, owner_rows = [], None
    if _subdivision_qa.OWNER in attrs:
        owners = await _subdivision_qa.load_owners(db, app_no)
        _survey = sd.get("survey_no") or sd.get("survey_number")
        owner_rows = await get_survey_owners(db, _survey, officer=officer) if _survey else None
    return _subdivision_qa.answer(attrs, app_no, sd, plots, owners, owner_rows, is_tamil)


async def _register_completion(db, officer, message: str):
    """Completion rate across every service code in the officer's jurisdiction.

    "What is my completion rate" counted only the ISD/NISD files assigned to the
    officer (38 of 57) while the register holds 105 completed of 152. A file is
    complete when it is approved or rejected, whatever its service code.
    """
    from backend.models import ServiceRegisterEntry as SRE
    ml = message.lower()
    is_this_month = any(p_ in ml for p_ in ["this month", "month", "monthly", "current month"])
    month_start = date.today().replace(day=1)
    period_start, period_end, period_label = _period_from_message(message)
    where = [SRE.ward_id.in_(officer.jurisdiction_ids or [])]
    done = SRE.status.in_(["approved", "rejected"])
    if period_start and period_end:
        win = and_(SRE.submission_date >= period_start, SRE.submission_date <= period_end)
        c_where, t_where = [*where, done, win], [*where, win]
        label = period_label or f"{period_start} to {period_end}"
    elif is_this_month:
        c_where = [*where, done, SRE.updated_at >= month_start]
        t_where = [*where, SRE.submission_date >= month_start]
        label = f"this month ({month_start.strftime('%B %Y')})"
    else:
        c_where, t_where, label = [*where, done], where, "overall"
    completed = await db.scalar(select(func.count()).select_from(SRE).where(and_(*c_where))) or 0
    total = await db.scalar(select(func.count()).select_from(SRE).where(and_(*t_where))) or 0
    return completed, total, label


async def _register_listing(db, officer, message: str, session_id, chat_history,
                            followup_ctx=None) -> dict:
    """An application listing across EVERY service code, scoped the way the
    ISD/NISD queue is: status, period, ward / block, channel, sort order.

    "Show my pending applications" used to answer from `applications`, which
    only holds ISD/NISD -- 17 of an officer's 53 pending files; the other
    service codes (0156, 0158, 0159, 0165, 0178, ...) were silently missing.
    This reads the flat register instead, so no service code is favoured, and
    reads the SAME scopes out of the message the ISD/NISD listing does so that
    "pending applications in June", "approved applications in ward 102" and
    "first 5 pending applications" all mean the same thing for every type. A
    question that names ISD/NISD, or something only they carry (overdue, field
    visits, per-file detail), never gets here -- see rag._is_register_wide_listing.
    """
    ml = message.lower()
    start_d, end_d = extract_date_range(message)
    month_scopes = extract_month_scopes(message)
    if month_scopes:
        start_d, end_d = month_scopes[0][0], month_scopes[-1][1]
    has_range = start_d is not None or end_d is not None
    negated = any(w in ml for w in ["not between", "not in", "outside", "other than",
                                    "இடைப்பட்டவை அல்ல", "தவிர"])
    year = month = None
    if not has_range:
        _ym = _year_match(message)
        year = int(_ym.group(1)) if _ym else None
        month = extract_month_from_query(message)
        if month and not year:
            year = _resolve_month_year(month)

    ward_num, block_num = await _geo_scope(db, session_id, message, chat_history, officer)
    # `_geo_scope()` only infers a ward from the PREVIOUS table when the
    # CURRENT message uses the word "ward" itself (just without a number) --
    # right for "how many in this ward", wrong for a bare filter-refinement
    # follow-up ("exclude rejected applications") that names no geography
    # word at all. That one silently widened from "ward 001" to the whole
    # jurisdiction. Only inherited when the carried context is ITSELF a
    # register-wide listing (never an unrelated prior topic), and never when
    # this message named its own ward/block.
    _carried_code = None
    _carried_excl_code = None
    if not ward_num and not block_num and followup_ctx is not None \
            and followup_ctx.intent == "all_service_code_applications":
        ward_num = ward_num or (followup_ctx.filters or {}).get("ward_number")
        block_num = block_num or (followup_ctx.filters or {}).get("block_number")
        _carried_code = (followup_ctx.filters or {}).get("service_code")
        _carried_excl_code = (followup_ctx.filters or {}).get("service_code_excluded")
    channels = extract_submission_channels(message) or None
    service_code = _requested_service_code_filter(message)
    excluded_service_code = _excluded_service_code_filter(message)
    if not service_code and not excluded_service_code and _carried_excl_code:
        excluded_service_code = _carried_excl_code
    # A bare continuation phrase ("exclude rejected applications", rewritten
    # by `_resolve_rejected_widen` to a fresh register-wide message that
    # names no service code of its own) used to drop whichever code the
    # prior turn was scoped to and silently widen to every code -- "show
    # applications for service code 0158" -> "exclude rejected applications"
    # answered from all 126 pending/approved applications across every
    # code, not the 20 under 0158. Same carry-forward rule as ward/block
    # above: only when THIS message names no code of its own and the carried
    # context is itself a register-wide listing.
    if not service_code and not excluded_service_code and _carried_code:
        service_code = _carried_code

    # Status. A named status always wins. With none named, a plain "show my
    # applications" is the open queue (pending), exactly as for ISD/NISD; a
    # period, a channel, a service code or an "all / total / new" word asks the
    # register instead and is not narrowed to pending.
    named = _explicit_status_request(ml)
    status = _requested_status_filter_for_register(message)
    # "Show pending applications for 0158." then "Exclude rejected
    # applications." -- rewritten upstream to "not rejected applications.",
    # which `_requested_status_filter_for_register` reads as the COMPLEMENT
    # of {rejected} across every status (pending/approved/in_progress/
    # escalated) -- correct in isolation, but this turn named no status of
    # its own; it only asked to drop rejected FROM THE LIST ALREADY ON
    # SCREEN. "Exclude rejected" after a pending-only chain should be a
    # no-op (rejected was never in it), not a broadening to every other
    # status too. When the carried chain's own starting status is a single
    # value already inside that complement, the officer's actual scope is
    # narrower than the negation alone implies -- intersect down to it
    # rather than handing back the wider complement.
    if (isinstance(status, list) and len(status) > 1
            and followup_ctx is not None and followup_ctx.intent == "all_service_code_applications"):
        _carried_status = (followup_ctx.filters or {}).get("base_query_filters", {}).get("status")
        if isinstance(_carried_status, str) and _carried_status in status:
            status = _carried_status
    wants_everything = bool(re.search(
        r"\b(?:all|every|total|new|recent|latest)\b|அனைத்து|மொத்த", ml))
    # neg_scope.rewrite() injects a literal "all" into a negated query ("applications
    # not from sro" -> "all application") just to keep it register-wide instead of
    # narrowed to the pending desk queue -- the officer never asked for "all". Taken
    # at face value that word also told get_all_service_code_applications() to stop
    # hiding rejected files, so "not from sro" silently included them while "from sro"
    # did not. When this listing is servicing a negation rewrite (_neg_scope.EXCLUDE
    # is still set -- cleared only later, by _neg_scope.apply()), the rejected-hiding
    # decision reads the officer's own typed words instead of the rewritten ones.
    wants_rejected_too = wants_everything
    if _neg_scope.EXCLUDE.get():
        wants_rejected_too = bool(re.search(
            r"\b(?:all|every|total|new|recent|latest)\b|அனைத்து|மொத்த", (_RAW_MESSAGE.get() or "").lower()))
    if named is None:
        if re.search(r"\bhistory\b", ml):
            status = ["approved", "rejected"]
        elif has_range or year or month or channels or service_code or excluded_service_code or wants_everything or (
                (ward_num or block_num) and re.search(r"\bhow\s+many\b|\bcount\b|\bnumber\s+of\b|எத்தனை", ml)):
            status = None   # a COUNT in a ward / block is over the register, not narrowed to the open queue
            # "Show pending applications for 0158." then "Exclude rejected
            # applications." -- the SECOND turn named no status of its own;
            # `wants_everything` is True only because `neg_scope.rewrite()`
            # injected the literal word "all" to keep this a register-wide
            # query rather than the narrower ISD/NISD queue (see the comment
            # on `wants_rejected_too` below). Taken at face value, that
            # widened "pending" (10 applications) into "every status except
            # rejected" (20) for a turn that only asked to drop rejected
            # files FROM THE LIST ALREADY ON SCREEN -- "exclude rejected"
            # after a pending-only chain should be a no-op (rejected was
            # never in it), not a broadening. Carrying the chain's own
            # starting status forward (same rule ward/block/service_code
            # already follow above) fixes it; a message that names its own
            # period/channel/code alongside the negation still correctly
            # reaches the register unrestricted, since those conditions on
            # their own already imply `wants_everything` with no rewrite
            # involved.
            if (_neg_scope.EXCLUDE.get() and not has_range and not year and not month
                    and not channels and not service_code and not excluded_service_code
                    and followup_ctx is not None and followup_ctx.intent == "all_service_code_applications"):
                _carried_status = (followup_ctx.filters or {}).get("base_query_filters", {}).get("status")
                if _carried_status:
                    status = _carried_status
        else:
            status = "pending"

    sort = _SORT_OVERRIDE.get() or extract_sort_order(message) or (None, None)
    sd = await get_all_service_code_applications(
        db, officer, service_code=service_code, exclude_service_code=excluded_service_code,
        submission_channel=channels,
        status=status, start_date=start_d, end_date=end_d,
        date_ranges=month_scopes or None, exclude_date_range=negated,
        submission_year=year, submission_month=month,
        ward_number=ward_num, block_number=block_num,
        sort_by=sort[0], sort_dir=sort[1],
        # The standing rule -- a rejected file is not in an operational list
        # unless asked for -- holds here too; "all"/"every" asks for it.
        hide_rejected=not wants_rejected_too)

    # Recorded so a follow-up ("only CSC", "which is oldest?") stays inside
    # this list's scope, the way the ISD/NISD listing records it.
    if channels:
        sd["submission_channels"] = list(channels)
        if len(channels) == 1:
            sd["submission_channel"] = channels[0]
    if ward_num:
        sd["ward_number"] = ward_num
    if block_num:
        sd["block_number"] = block_num
    if service_code:
        sd["service_code"] = service_code
    if month:
        sd["submission_month"] = month
    if year:
        sd["submission_year"] = year
    if has_range:
        if month_scopes:
            sd["period_label"] = format_month_scopes(month_scopes)
        elif start_d and end_d and _whole_month_label(start_d, end_d):
            sd["period_label"] = _whole_month_label(start_d, end_d)
        else:
            sd["period_label"] = f"{start_d or '...'} to {end_d or '...'}"
    elif month:
        sd["period_label"] = f"{_MONTH_NAMES[month]} {year}" if year else _MONTH_NAMES[month]
    elif year:
        sd["period_label"] = str(year)
    if negated and has_range:
        sd["exclude_date_range"] = True
    # "Restore the original filter." needs something stable to restore TO --
    # the scope this listing started from, before any negation/narrowing
    # follow-up changed it. Carried forward unchanged once set (the FIRST
    # register-wide listing in the chain records it; every later re-listing
    # in the SAME chain -- "not rejected", "include rejected too", a column
    # projection -- just repeats the one already carried), so "restore"
    # always means "back to the very first scope", not "back to one step
    # ago". See `_restore_original_filter_answer`.
    # Not gated on `followup_ctx.intent` -- a row-slicing / exclusion turn in
    # between ("show only the first five rows", "exclude the second row")
    # answers through `followup_list`, not `all_service_code_applications`,
    # but `_followup_out_context` already carries `base_query_filters`
    # through THOSE turns untouched (it is in the whitelist `build_context`
    # copies forward and is never one of the keys a scoped re-query sets).
    # Checking the intent here anyway (as an earlier version of this did)
    # meant any such turn landing between the original listing and the next
    # full re-listing silently reset the snapshot to whatever happened to be
    # active right then -- "include rejected too" after an "exclude the
    # second row" turn took its OWN unfiltered, ward-less scope as if it
    # were the original.
    _carried_base = (followup_ctx.filters or {}).get("base_query_filters") if followup_ctx is not None else None
    if not _carried_base:
        # The immediately-prior turn may itself have lost it -- a bare "show
        # row 3" with no field attached resolves to a single full-details
        # card (`application_status`), whose own saved context carries no
        # memory of the register listing it was picked from at all. Scan
        # back through the conversation the same way `_restore_original_
        # filter_answer` does, so a one-turn detour like that does not reset
        # the whole chain's snapshot to whatever this turn's own filters are.
        _carried_base = await _find_base_query_filters(db, session_id, officer.officer_id if officer else None)
    # A chain only continues when THIS query's own resolved scope agrees
    # with the carried snapshot -- "show rejected applications in ward 005"
    # after a ward-001 chain names a genuinely different ward, so it starts
    # a NEW chain instead of inheriting the old one. Without this, "restore
    # the original filter" several turns later would reach past the ward-005
    # listing the officer is actually working from and hand back the
    # obsolete ward-001 scope purely because it happens to sit earlier in
    # the conversation. Only compared when BOTH sides actually name a value
    # (an unscoped dimension on either side is not a conflict) -- an
    # inherited, unnamed ward_num that happens to already equal the
    # carried one is correctly not a boundary.
    if _carried_base and (
            (ward_num and _carried_base.get("ward_number") and ward_num != _carried_base["ward_number"])
            or (block_num and _carried_base.get("block_number") and block_num != _carried_base["block_number"])
            or (service_code and _carried_base.get("service_code") and service_code != _carried_base["service_code"])):
        _carried_base = None
    if _carried_base:
        sd["base_query_filters"] = _carried_base
    else:
        sd["base_query_filters"] = {
            "service_code": service_code,
            "submission_channel": list(channels) if channels else None,
            "status": status, "start_date": start_d, "end_date": end_d,
            "date_ranges": month_scopes or None, "exclude_date_range": negated,
            "submission_year": year, "submission_month": month,
            "ward_number": ward_num, "block_number": block_num,
            "hide_rejected": not wants_rejected_too,
        }
    return sd


# "Restore the original filter." / "restore the initial filter." -- back to
# the scope the register-listing CHAIN started from (`base_query_filters`,
# snapshotted once per chain just above and carried forward unchanged by
# every later re-listing in it). Deliberately narrow: only the explicit
# "restore ... filter" phrasing claims the turn, and only when a snapshot
# is actually on record -- there is no sense in which guessing a filter is
# better than asking, and before this fix the message named no field/row/
# column word at all, so it fell through every other follow-up layer to the
# LLM, which (per CLAUDE.md's own documented pattern for this) improvised an
# unrelated jurisdiction refusal from stale ward numbers in chat_history.
_RESTORE_FILTER_RE = re.compile(
    r"\brestore\b.{0,25}\b(?:original|initial|previous|earlier|first|default)\b.{0,15}\bfilter",
    re.IGNORECASE)


async def _find_base_query_filters(db, session_id, officer_id):
    """Scan recent turns of this session for the last `base_query_filters`
    snapshot on record, newest first.

    The immediate carried context is tried first by the caller; this is the
    fallback for a chain where the MOST RECENT turn does not carry it even
    though an earlier one in the same conversation does -- a bare "show row
    3" / "show the third row now" with no field attached resolves to a
    single full application card (`application_status`), whose own saved
    context is built from that answer alone and never mentions the register
    listing it was picked from at all. Reuses the exact windowed query
    `_load_followup_context` already runs, so this never reaches further
    back than an ordinary follow-up would.
    """
    if db is None or not session_id:
        return None
    try:
        _cutoff = datetime.now(timezone.utc) - timedelta(minutes=settings.FOLLOWUP_CONTEXT_TTL_MINUTES)
        rows = (await db.execute(
            select(ChatMessage.structured_data)
            .where(and_(ChatMessage.session_id == session_id,
                        ChatMessage.role == "assistant",
                        ChatMessage.created_at >= _cutoff,
                        messages_since_session_start(session_id)))
            .order_by(ChatMessage.created_at.desc())
            .limit(_FOLLOWUP_CONTEXT_WINDOW)
        )).scalars().all()
    except Exception:  # pragma: no cover - a convenience, never fatal
        return None
    for raw in rows:
        if isinstance(raw, dict) and (raw.get("filters") or {}).get("base_query_filters"):
            return raw["filters"]["base_query_filters"]
    return None


async def _restore_original_filter_answer(db, officer, message: str, ctx, language: str,
                                          session_id=None, officer_id=None):
    if not (ctx and _RESTORE_FILTER_RE.search(message or "")):
        return None
    is_tamil = language in ("ta", "tanglish")
    base = (ctx.filters or {}).get("base_query_filters") \
        or await _find_base_query_filters(db, session_id, officer_id)
    if not base:
        # Nothing stable on record for THIS conversation to go back to --
        # asking is the honest answer, not inventing one of the filters the
        # officer happened to type along the way. `sd=None` tells the caller
        # to keep the existing carried context exactly as it was.
        return (
            "இந்த உரையாடலில் மீட்டெடுக்க ஒரு பதிவு செய்யப்பட்ட அசல் வடிகட்டி இல்லை. "
            "எந்த வடிகட்டியை (நிலை, வார்டு, வழி, காலம்) மீட்டெடுக்க வேண்டும் என்று கூறவும்."
            if is_tamil else
            "There is no original filter on record for this conversation to restore -- "
            "say which filter (status, ward, channel, period) you want back, or ask "
            "for the listing again from scratch."
        ), None
    sd = await get_all_service_code_applications(db, officer, **base)
    sd["base_query_filters"] = base
    if base.get("ward_number"):
        sd["ward_number"] = base["ward_number"]
    if base.get("block_number"):
        sd["block_number"] = base["block_number"]
    body = _render_all_service_code_answer(sd, is_tamil=is_tamil)
    lead = ("அசல் வடிகட்டி மீட்டெடுக்கப்பட்டது -- வரிசை மற்றும் நெடுவரிசைகள் மாறவில்லை." if is_tamil
            else "Original filter restored -- sort order and column selection are unchanged.")
    return f"<div class='table-intro'>{lead}</div>{body}", sd


_DISTINCT_SERVICE_COUNT_RE = re.compile(
    r"\bhow\s+many\s+(?:service\s*codes?|services)\b|\bnumber\s+of\s+(?:service\s*codes?|services)\b|"
    r"எத்தனை\s*சேவை(?:\s*குறியீடு)?(?:கள்)?",
    re.IGNORECASE)


def _asks_distinct_service_count(message: str) -> bool:
    """"How many services currently have pending applications?" / "how many
    service codes have pending files?" counts SERVICES, not applications -- a
    different question from "how many applications are pending", which
    `_is_count_only_query` already answers correctly with the application
    total. The counted noun right after "how many" is "service(s)" / "service
    code(s)", never "application(s)", so this never claims a genuine
    application-count question such as "how many applications does 0158
    have"."""
    return bool(_DISTINCT_SERVICE_COUNT_RE.search(message or ""))


def _render_all_service_code_answer(data: dict, is_tamil: bool = False,
                                    count_only: bool = False,
                                    distinct_services: bool = False) -> str:
    """A flat table across every TAMILNILAM service code, from
    `get_all_service_code_applications()`'s `service_register_entries` rows.
    Same column layout as the ISD/NISD applications table (Application No. /
    Type / Survey No. / Sub-Divisions / Status / Stage / Submitted / Ward /
    Block) so the two read as one family. Survey No. and Sub-Divisions are real
    (every service code carries them in the source extract); Stage is a coarse
    Open/Completed read off the extract's own C/P workflow marker, not a
    multi-desk chain.

    Every service code is treated alike -- none is singled out or footnoted.
    The per-code breakdown and the totals are counted from the rows actually
    shown (after any negation or "first N" cap), never from the pre-cap query.
    A question that names ISD/NISD, or something only they carry, is answered
    by the ISD/NISD handler instead and never reaches this renderer.
    """
    from html import escape as _e
    from backend.services.rag import _status, _app_link
    from backend.utils.helpers import SIS_URBAN_SERVICES
    if not data:
        return ""
    apps = data.get("applications") or []
    count = data.get("count", len(apps))
    _chan_label = {"CSC": "CSC", "citizen": "citizen portal", "sub_registrar": "Sub-Registrar"}

    # ---- what the officer asked for, in words -------------------------------
    st = data.get("status_filter")
    st_list = st if isinstance(st, list) else ([st] if st else [])
    st_words = " & ".join(_STATUS_LABELS.get(x, str(x).title()).lower() for x in st_list)
    chans = data.get("channel_filter")
    chans = list(chans) if isinstance(chans, (list, tuple, set)) else ([chans] if chans else [])
    chan_name = " / ".join(_chan_label.get(c, c) for c in chans)
    svc_code = data.get("service_code_filter")
    svc_name = (SIS_URBAN_SERVICES.get(svc_code, {}) or {}).get("name", svc_code) if svc_code else None
    excl_code = data.get("service_code_excluded")
    excl_name = (SIS_URBAN_SERVICES.get(excl_code, {}) or {}).get("name", excl_code) if excl_code else None
    period = data.get("period_label")
    if period and data.get("exclude_date_range"):
        period = f"not {period}"
    geo = []
    if data.get("ward_filter"):
        geo.append(f"Ward {data['ward_filter']}")
    if data.get("block_filter"):
        geo.append(f"Block {data['block_filter']}")

    scope_en = " ".join(x for x in [
        st_words,
        "application(s)",
        f"from {chan_name}" if chan_name else "",
        f"under {svc_code} ({svc_name})" if svc_code else "",
        f"excluding service code {excl_code} ({excl_name})" if excl_code else "",
        f"in {period}" if period else "",
        f"in {' / '.join(geo)}" if geo else "",
    ] if x)
    if data.get("excluded"):
        scope_en += f" ({str(data.get('query_type') or '').replace('Applications', '').strip(' ()')})"

    # ---- per-code breakdown, from the rows kept -----------------------------
    by_svc: dict = {}
    by_chan: dict = {}
    for a in apps:
        by_svc[a.get("service_code")] = by_svc.get(a.get("service_code"), 0) + 1
        if a.get("submission_channel"):
            by_chan[a["submission_channel"]] = by_chan.get(a["submission_channel"], 0) + 1
    svc_summary = ", ".join(f"{code} ({n})" for code, n in sorted(by_svc.items(), key=lambda kv: str(kv[0])))
    chan_summary = ", ".join(f"{n} {_chan_label.get(c, c)}" for c, n in sorted(by_chan.items()))

    hidden = data.get("rejected_hidden") or 0
    hidden_note_en = (f" {hidden} rejected application(s) matching this are left out; "
                      f"ask for rejected applications to see them." if hidden else "")
    hidden_note_ta = (f" இதனுடன் பொருந்தும் {hidden} நிராகரிக்கப்பட்ட விண்ணப்பங்கள் சேர்க்கப்படவில்லை." if hidden else "")

    # "How many services currently have pending applications?" counts the
    # DISTINCT service codes in `by_svc` (one entry per code actually present
    # in the filtered rows -- never a hardcoded or manually maintained list),
    # not `count` (the application total `by_svc`'s own values sum to). Zero
    # qualifying services is stated explicitly, never silently folded into
    # the generic "no applications found" wording below.
    if distinct_services:
        n_services = len(by_svc)
        if is_tamil:
            _ta_status = " ".join({"pending": "நிலுவையில் உள்ள", "approved": "அங்கீகரிக்கப்பட்ட",
                                    "rejected": "நிராகரிக்கப்பட்ட"}.get(x, x) for x in st_list)
            qualifier = " ".join(x for x in [
                f"{period} இல்" if period else "", f"{' / '.join(geo)} இல்" if geo else "",
                f"{chan_name} வழியாக" if chan_name else "", _ta_status,
            ] if x)
            intro = (f"{qualifier + ' ' if qualifier else ''}{n_services} சேவை(கள்) நிலுவையில் உள்ள விண்ணப்பங்களைக் "
                     f"கொண்டுள்ளன (மொத்தம் {count} விண்ணப்பங்கள்)" +
                     (f" — {svc_summary}." if svc_summary else "."))
        else:
            status_word = f"{st_words} " if st_words else "pending "
            scope_bits = " ".join(x for x in [
                f"from {chan_name}" if chan_name else "",
                f"in {period}" if period else "",
                f"in {' / '.join(geo)}" if geo else "",
            ] if x)
            intro = (f"<strong>{n_services}</strong> service code(s) currently have {status_word}applications"
                     f"{(' ' + scope_bits) if scope_bits else ''} ({count} application{'s' if count != 1 else ''} in all)" +
                     (f": {svc_summary}." if svc_summary else "."))
        intro += hidden_note_ta if is_tamil else hidden_note_en
        return f"<div class='table-intro'>{intro}</div>"

    if not apps:
        if is_tamil:
            note = "உங்கள் அதிகார எல்லையில் பொருந்தும் விண்ணப்பங்கள் இல்லை." + hidden_note_ta
        else:
            note = f"No {scope_en} found in your jurisdiction.{hidden_note_en}".replace("application(s)", "applications", 1)
            if data.get("empty_note") and not (st_words or period or geo or chan_name or svc_code):
                note = data["empty_note"]
        return f"<div class='table-intro'>{_e(note)}</div>"

    across = "" if svc_code else (
        f" across every service code in your jurisdiction ({svc_summary})" if svc_summary else "")
    if is_tamil:
        _ta_st = {"pending": "நிலுவையில் உள்ள", "approved": "அங்கீகரிக்கப்பட்ட",
                  "rejected": "நிராகரிக்கப்பட்ட"}
        _ta_status = " ".join(_ta_st.get(x, x) for x in st_list)
        _ta_bits = [b for b in [
            f"{period} இல்" if period else "",
            f"{' / '.join(geo)} இல்" if geo else "",
            f"{chan_name} வழியாக" if chan_name else "",
        ] if b]
        intro = (f"உங்கள் அதிகார எல்லையில் {' '.join(_ta_bits) + ' ' if _ta_bits else ''}"
                 f"{_ta_status + ' ' if _ta_status else ''}{count} விண்ணப்பங்கள் "
                 f"({'அனைத்து சேவை குறியீடுகளிலும்' if not svc_code else svc_code}) — {svc_summary}.")
        if not svc_code and not chans and chan_summary:
            intro += f" வழிவாரியாக: {chan_summary}."
    else:
        intro = f"Found <strong>{count}</strong> {_e(scope_en)}{_e(across)}."
        if not svc_code and not chans and chan_summary:
            intro += f" By channel: {chan_summary}."
    lim = data.get("result_limit")
    if isinstance(lim, dict) and not lim.get("out_of_range") and lim.get("total"):
        which = "last" if lim.get("end") == "tail" else "first"
        if lim.get("end") == "head_nth":
            intro += f" Showing result {lim.get('n')} of {lim['total']}."
        elif lim.get("end") != "rows":
            intro += f" Showing the {which} {lim.get('n')} of {lim['total']}."
    elif isinstance(lim, dict) and lim.get("out_of_range"):
        intro += f" There is no result at that position; the list has {lim.get('total')}."
    intro += hidden_note_ta if is_tamil else hidden_note_en
    if count_only:
        return f"<div class='table-intro'>{intro}</div>"

    head = ("<tr><th>Application No.</th><th>Type</th><th>Survey No.</th>"
            "<th>Sub-Divisions</th><th>Status</th><th>Stage</th><th>Submitted</th>"
            "<th>Ward</th><th>Block</th></tr>")
    if is_tamil:
        head = ("<tr><th>விண்ணப்ப எண்</th><th>வகை</th><th>சர்வே எண்</th>"
                "<th>உட்பிரிவுகள்</th><th>நிலை</th><th>நிலை (Stage)</th>"
                "<th>சமர்ப்பிக்கப்பட்ட தேதி</th><th>வார்டு</th><th>தொகுதி</th></tr>")

    def _type_label(a):
        name = a.get("service_name")
        return name if name and name != "Unknown service" else (a.get("service_code") or "-")

    def _named(number, name):
        # The ward master's own ename is a dumped record, not a display name --
        # "1 (021) Orakadam (Ward:A)" -- so the readable part is pulled out
        # rather than shown (or appended to the number) verbatim.
        number = number or "-"
        if not name or name in ("N/A", "-"):
            return number
        m = re.match(r'^\s*\d+\s*\(\d+\)\s*(.+?)\s*\(Ward:', name, re.IGNORECASE)
        clean = m.group(1).strip() if m else name.strip()
        return clean if clean and clean != number else number

    rows = ""
    for a in apps:
        rows += (
            "<tr>"
            f"<td>{_app_link(a.get('application_number'))}</td>"
            f"<td>{_e(_type_label(a))}</td>"
            f"<td>{_e(a.get('survey_no') or '-')}</td>"
            f"<td>{_e(a.get('subdivision_no') or '-')}</td>"
            f"<td>{_status(a.get('status') or 'pending', 'ta' if is_tamil else 'en')}</td>"
            f"<td>{_e(a.get('stage') or '-')}</td>"
            f"<td>{_e(a.get('submission_date') or '-')}</td>"
            f"<td>{_e(_named(a.get('ward_number'), a.get('ward_name')))}</td>"
            f"<td>{_e(_named(a.get('block_number'), a.get('block_name')))}</td>"
            "</tr>"
        )
    return (f"<div class='table-intro'>{intro}</div>"
            f"<table class='data-table'><thead>{head}</thead><tbody>{rows}</tbody></table>")


def _comparison_answer(data: dict, is_tamil: bool = False) -> str:
    text = _comparison_answer_core(data, is_tamil)
    if data and data.get("found") and data.get("scope_note"):
        text = f"{text} {data['scope_note']}"
    return text


def _comparison_answer_core(data: dict, is_tamil: bool = False) -> str:
    """Render a comparison the officer can act on -- both sides, and the verdict.

    A table of one side is not a comparison, and neither is a two-row status
    dump: the question asks which, so the answer says which, and by how much.
    """
    if not data or not data.get("found"):
        return (data or {}).get("message") or (
            "அந்த ஒப்பீட்டைப் பதிவேட்டில் இருந்து என்னால் கணக்கிட முடியவில்லை."
            if is_tamil else
            "I could not work that comparison out from the register.")

    kind = data.get("kind")
    if kind == "applications":
        left, right = data["left"], data["right"]
        aspect = data.get("aspect")
        lines = [f"**{left['application_number']}** vs **{right['application_number']}**"]
        _fields_en = (("Type", "type"), ("Status", "status"),
                      ("Filed", "submission_date"), ("Decided", "decision_date"),
                      ("Days to decide", "days_to_decide"),
                      ("Survey", "survey_no"), ("Ward", "ward_number"),
                      ("Channel", "submission_channel"), ("Area (sq.m)", "area_sqm"))
        _fields_ta = ("வகை", "நிலை", "சமர்ப்பித்த தேதி", "முடிவு தேதி",
                     "முடிவெடுக்க எடுத்த நாட்கள்", "கணக்கெண்", "வார்டு",
                     "வழி", "பரப்பளவு (ச.மீ)")
        _na = "இல்லை" if is_tamil else "N/A"
        for (label_en, key), label_ta in zip(_fields_en, _fields_ta):
            lv, rv = left.get(key), right.get(key)
            if lv in (None, "", "N/A") and rv in (None, "", "N/A"):
                continue
            label = label_ta if is_tamil else label_en
            if is_tamil and key == "status":
                lv = _compare_label("status", lv, True) if lv not in (None, "") else lv
                rv = _compare_label("status", rv, True) if rv not in (None, "") else rv
            elif is_tamil and key == "submission_channel":
                lv = _compare_label("channel", lv, True) if lv not in (None, "") else lv
                rv = _compare_label("channel", rv, True) if rv not in (None, "") else rv
            lines.append(f"• **{label}**: {lv if lv not in (None, '') else _na}"
                         f"  |  {rv if rv not in (None, '') else _na}")
        verdict = data.get("verdict")
        if verdict:
            lines.append("")
            lines.append(verdict)
        elif aspect is None:
            lines.append("")
            if is_tamil:
                lines.append("இவற்றில் ஒன்றின் தீர்ப்புக்கு \"எது அதிக நேரம் "
                             "எடுத்தது\" அல்லது \"எது பழையது\" எனக் கேளுங்கள்.")
            else:
                lines.append("Ask \"which took longer\" or \"which is older\" for a verdict "
                             "on one of these.")
        return "\n".join(lines)

    if kind == "period":
        sides = data.get("sides") or []
        if not sides:
            return ("அந்தக் கேள்வியில் இருந்து இரண்டு காலகட்டங்களை என்னால் "
                    "படிக்க முடியவில்லை." if is_tamil else
                    "I could not read two periods out of that question.")
        named = ", ".join(f"{s['label']} {s['count']}" for s in sides)
        top = max(sides, key=lambda s: s["count"])
        low = min(sides, key=lambda s: s["count"])
        if is_tamil:
            head = f"சமர்ப்பிக்கப்பட்ட விண்ணப்பங்கள் — {named}."
            if top["count"] == low["count"]:
                return f"{head} இரண்டும் சமம்."
            gap = top["count"] - low["count"]
            pct = f" ({gap * 100 // low['count']}% அதிகம்)" if low["count"] else ""
            return f"{head} {top['label']}, {low['label']} விட {gap}{pct} அதிகம்."
        head = f"Applications filed — {named}."
        if top["count"] == low["count"]:
            return f"{head} The two are level."
        gap = top["count"] - low["count"]
        pct = f" ({gap * 100 // low['count']}% more)" if low["count"] else ""
        return (f"{head} {top['label']} is ahead of {low['label']} by "
                f"{gap}{pct}.")

    if kind == "average_duration":
        if is_tamil:
            scope = f"{_compare_label('status', data['status'], True)} " if data.get("status") else "முடிவு செய்யப்பட்ட "
            return (f"உங்கள் {data['population']} {scope}விண்ணப்பங்களில் சமர்ப்பிப்பு முதல் "
                    f"முடிவு வரையிலான சராசரி நேரம் {data['average_days']} நாட்கள் "
                    f"(நடுநிலை {data['median_days']}, வேகமானது {data['fastest_days']}, "
                    f"மெதுவானது {data['slowest_days']}).")
        scope = f"{data['status']} " if data.get("status") else "decided "
        return (f"Across your {data['population']} {scope}applications the mean "
                f"time from filing to decision is {data['average_days']} days "
                f"(median {data['median_days']}, fastest {data['fastest_days']}, "
                f"slowest {data['slowest_days']}).")

    if kind == "month":
        runners = ", ".join(f"{s['label']} {s['count']}"
                            for s in (data.get("sides") or [])[1:3])
        if is_tamil:
            which = "அதிக விண்ணப்பங்கள் வந்த" if data.get("extreme") != "min" else "குறைவான விண்ணப்பங்கள் வந்த"
            head = (f"{which} மாதம் **{data['label']}** — {data['count']} "
                    f"விண்ணப்பங்கள், மொத்தம் {data['months']} மாதங்களில்.")
            return head + (f" அடுத்தது: {runners}." if runners else "")
        which = "busiest" if data.get("extreme") != "min" else "quietest"
        head = (f"The {which} month was **{data['label']}** with "
                f"{data['count']} application"
                f"{'s' if data['count'] != 1 else ''}, out of "
                f"{data['months']} months on record.")
        return head + (f" Next: {runners}." if runners else "")

    if kind in ("type", "status", "channel") and data.get("aspect") == "duration":
        sides = [s for s in (data.get("sides") or []) if s.get("days") is not None]
        empty = [s["label"] for s in (data.get("sides") or [])
                 if s.get("days") is None]
        if not sides:
            return ("இரு பக்கத்திலும் ஒப்பிட முடிவு செய்யப்பட்ட விண்ணப்பம் "
                    "இல்லை, எனவே ஒப்பிட நேரம் இல்லை." if is_tamil else
                    "Neither side has a decided application to measure, so "
                    "there is no time to compare.")
        named = ", ".join(f"{_compare_label(kind, s['label'], is_tamil)} "
                          f"{s['days']} {'நாட்கள்' if is_tamil else 'days'} "
                          f"({'மொத்தம்' if is_tamil else 'over'} {s['population']})"
                          for s in sides)
        if is_tamil:
            head = f"சமர்ப்பிப்பு முதல் முடிவு வரையிலான சராசரி நேரம் — {named}."
            if len(sides) < 2:
                return (head + f" {', '.join(_compare_label(kind, e, True) for e in empty)} "
                        f"ஒப்பிட முடிவு செய்யப்பட்டது எதுவும் இல்லை.")
            slow = max(sides, key=lambda s: s["days"])
            fast = min(sides, key=lambda s: s["days"])
            if slow["days"] == fast["days"]:
                return f"{head} இரண்டும் சமம்."
            return (f"{head} {_compare_label(kind, slow['label'], True)}, "
                    f"{_compare_label(kind, fast['label'], True)} விட "
                    f"{round(slow['days'] - fast['days'], 1)} நாட்கள் அதிகம் எடுக்கும்.")
        head = f"Mean time from filing to decision — {named}."
        if len(sides) < 2:
            return (head + f" {', '.join(_compare_label(kind, e) for e in empty)} "
                    f"has nothing decided to compare against.")
        slow = max(sides, key=lambda s: s["days"])
        fast = min(sides, key=lambda s: s["days"])
        if slow["days"] == fast["days"]:
            return f"{head} The two are level."
        return (f"{head} {_compare_label(kind, slow['label'])} takes "
                f"{round(slow['days'] - fast['days'], 1)} days longer than "
                f"{_compare_label(kind, fast['label'])}.")

    if kind in ("type", "status", "channel", "ward"):
        sides = data.get("sides") or []
        if not sides:
            return ("ஒப்பிடுவதற்கு இருபுறமும் எதுவும் இல்லை." if is_tamil else
                    "There is nothing on either side of that comparison.")
        named = ", ".join(f"{_compare_label(kind, s['label'], is_tamil)} {s['count']}"
                          for s in sides)
        _kind_ta = {"type": "வகை", "status": "நிலை", "channel": "வழி",
                   "ward": "வார்டு"}.get(kind, kind)
        if len(sides) == 1:
            # Nothing to compare against -- an officer holding one ward asking
            # "which ward has more" was told "they are level".
            only = sides[0]
            if is_tamil:
                return (f"உங்கள் அதிகார வரம்பில் ஒப்பிட ஒரே ஒரு {_kind_ta} மட்டுமே "
                        f"உள்ளது: {_compare_label(kind, only['label'], True)}, "
                        f"{only['count']} விண்ணப்பங்கள்.")
            return (f"There is only one {kind} in your jurisdiction to compare: "
                    f"{_compare_label(kind, only['label'])}, with "
                    f"{only['count']} application"
                    f"{'s' if only['count'] != 1 else ''}.")
        top = max(sides, key=lambda s: s["count"])
        low = min(sides, key=lambda s: s["count"])
        if is_tamil:
            head = f"{named} (உங்கள் அதிகார வரம்பில் மொத்தம் {data.get('total', 0)})."
            if top["count"] == low["count"]:
                return f"{head} இரண்டும் சமம்."
            gap = top["count"] - low["count"]
            return (f"{head} {_compare_label(kind, top['label'], True)}, "
                    f"{_compare_label(kind, low['label'], True)} விட {gap} அதிகம்.")
        head = f"{named} (of {data.get('total', 0)} in your jurisdiction)."
        if top["count"] == low["count"]:
            return f"{head} They are level."
        gap = top["count"] - low["count"]
        return (f"{head} {_compare_label(kind, top['label'])} leads "
                f"{_compare_label(kind, low['label'])} by {gap}.")

    if kind == "superlative":
        tied = data.get("tied_with") or []
        _status_ta_s = {"pending": "நிலுவையில்", "approved": "அங்கீகரிக்கப்பட்டது",
                       "rejected": "நிராகரிக்கப்பட்டது", "in_progress": "செயல்பாட்டில்",
                       "escalated": "மேல்நிலைப்படுத்தப்பட்டது"}.get(
            str(data.get("status") or "").lower(), data.get("status"))
        if is_tamil:
            which = "அதிக நேரம் எடுத்தது" if data.get("extreme") != "min" else "வேகமாக முடிந்தது"
            pop_status_ta = {"decided": "முடிவு செய்யப்பட்ட"}.get(
                data.get("population_status") or "decided", data.get("population_status") or "முடிவு செய்யப்பட்ட")
            head = (f"{which} **{data['application_number']}** "
                    f"({data['application_type']}, {_status_ta_s}): "
                    f"{data['days']} நாட்கள், {data['submission_date']} அன்று "
                    f"சமர்ப்பிக்கப்பட்டு {data['decision_date']} அன்று முடிவானது. "
                    f"உங்கள் மேசையில் உள்ள {data['population']} "
                    f"{pop_status_ta} விண்ணப்பங்களில் நடுநிலை "
                    f"{data['median_days']} நாட்கள்.")
            if tied:
                listed = ", ".join(tied[:3]) + ("…" if len(tied) > 3 else "")
                head += (f" மற்ற {len(tied)} விண்ணப்பங்களும் அதே அளவு நேரம் "
                        f"எடுத்தன ({listed}).")
            return head
        which = "longest" if data.get("extreme") != "min" else "quickest"
        head = (f"The {which} was **{data['application_number']}** "
                f"({data['application_type']}, {data['status']}): "
                f"{data['days']} days, filed {data['submission_date']} and "
                f"decided {data['decision_date']}. Across the "
                f"{data['population']} "
                f"{data.get('population_status') or 'decided'} applications on "
                f"your desk the median is {data['median_days']} days.")
        if tied:
            listed = ", ".join(tied[:3]) + ("…" if len(tied) > 3 else "")
            head += (f" {len(tied)} other application"
                     f"{'s' if len(tied) != 1 else ''} took exactly as long "
                     f"({listed}).")
        return head

    return ("அந்த ஒப்பீட்டைப் பதிவேட்டில் இருந்து என்னால் கணக்கிட முடியவில்லை."
            if is_tamil else
            "I could not work that comparison out from the register.")


# "Do they have an IGRS number?" asked of a list. The table cannot answer a
# yes/no, and the channel settles it: an IGRS Form 6 number is raised only
# where the Sub-Registrar's IGRS built the mutation off a registered deed, so
# every sub_registrar file carries one and no CSC or citizen file does.
_IGRS_QUESTION_RE = re.compile(
    r"\bigrs\b|\bform\s*6\b|\bform6\b|படிவம்\s*6", re.IGNORECASE)


# ── IGRS / CAN asked as a RULE, not about a file ─────────────────────────────
# "If the IGRS number is absent, what does it mean -- so it is not from SRO?"
# is a question about the rule, and it must not be answered with a table of
# applications. Two things used to make it one: the officer's word "IGRS" is
# read as a Sub-Registrar channel filter (correctly, for "which of MY
# applications have an IGRS number"), and the LLM fallback had almost nothing
# in the corpus to work from -- "SRO" appears nowhere in it, so "what is SRO"
# came back as "the query was refused, which means it is outside the
# jurisdiction of the officer", which is not even the right kind of answer.
#
# These are documented invariants, not counts, so they are answered in Python
# rather than left to the model. The same statements are in
# backend/documents/land_rules.txt for retrieval.

# Asking about the rule outright.
_RULE_STRONG_RE = re.compile(
    r"\bif\b|\bwhat\s+does\s+(?:it|that|this|an?)\b|\bmeans?\b|\bmeaning\b"
    r"|\bwhy\b|\bsame\s+as\b|\bdifference\b"
    r"|\bwhich\s+applications\s+(?:get|carry|have)\b|\bwho\s+(?:gets|issues)\b"
    r"|\bstand\s+for\b|\bfull\s+form\b"
    r"|என்றால்|அர்த்தம்|ஏன்",
    re.IGNORECASE,
)
# Asking for a definition. The article carries the whole distinction: "what is
# A can number" wants the definition, "what is THE can number" wants this
# application's -- and the second is the commonest follow-up there is, so it
# must not be claimed here.
_RULE_DEFN_RE = re.compile(
    r"\b(?:sro|igrs|can|csc|sub[\s-]?registrar)\s*(?:number\s*)?(?:na|naa)\s+(?:enna|yaaru|yaru|yar)\b"
    r"|\bwhat\s+(?:is|are)\s+(?:a|an)\b"
    r"|\bwhat\s+(?:is|are)\s+(?:sro|igrs|can)\b"
    r"|\bwhat\s+is\s+igrs\s+form\b",
    re.IGNORECASE,
)
# "CAN எண் என்ன" -- bare Tamil "என்ன" ("what") after the subject, the plainer
# twin of "என்றால் என்ன" ("what does X mean") above. Tamil has no articles, so
# unlike "a can number" vs "the can number" in English, this exact phrasing is
# also the commonest follow-up ("status of <app>" then "CAN எண் என்ன?" wants
# THAT application's CAN, not the definition). Kept separate from
# `_RULE_STRONG_RE` so the caller can drop it when an application is already
# in view -- weak on its own, strong only when nothing else already answers it.
_TAMIL_BARE_WHAT_RE = re.compile(r"என்ன")


def _is_rule_shaped(msg: str, allow_bare_tamil_what: bool = True) -> bool:
    if _RULE_STRONG_RE.search(msg) or _RULE_DEFN_RE.search(msg):
        return True
    return allow_bare_tamil_what and bool(_TAMIL_BARE_WHAT_RE.search(msg))
_SRO_RE = re.compile(r"\bsro\b|\bsub[\s-]?registrar\b", re.IGNORECASE)
# "who is the sub registrar", "what does the SRO do", "what is the role of the
# sub registrar", "sub registrar யார்" -- role questions about the office. None
# of them matched the generic rule shapes ("what is A ..." / "who gets"), so
# they fell through to `sale_deed_check`, which answered *"Please specify the
# application number you are asking about"* to a question that names no
# application and wants none.
_SRO_ROLE_RE = re.compile(
    r"\bwho\s+(?:is|are|handles?|does)\b|\bwhat\s+(?:is|are)\b"
    r"|\brole\s+of\b|\bwhat\s+does\b|\bmeaning\b|\bstands?\s+for\b"
    r"|\bexplain\b|\bfull\s+form\b",
    re.IGNORECASE,
)
# Meta words: they describe the SHAPE of an identifier, which only the rule
# has. See the use in `_igrs_can_rule_topic`.
_META_FIELD_RE = re.compile(
    r"\bformat\b|\blength\b|\bhow\s+long\b|\bhow\s+many\s+digits\b"
    r"|\bdigits?\b|\bstructure\b|\bpattern\b|\bmade\s+up\s+of\b"
    r"|\bcharacters\b|வடிவ|நீளம்|இலக்க",
    re.IGNORECASE,
)
_ABSENT_RE = re.compile(
    r"\babsent\b|\bmissing\b|\bempty\b|\bblank\b|\bno\s+igrs\b|\bnot\s+have\b"
    r"|\bwithout\b|\bdoes\s?n[o']?t\s+have\b|\bhas\s+no\b|\bnone\b|\bnil\b"
    r"|இல்ல",
    re.IGNORECASE,
)


# "on what basis / how do you decide / how do you know" -- a question about the
# derivation, not about the files it was applied to.
_CHANNEL_BASIS_RE = re.compile(
    r"\bon\s+what\s+bas(?:is|ed)\b|\bbased\s+on\s+what\b|\bwhat\s+bas(?:is|ed)\b"
    r"|\bhow\s+(?:do|did|does|can|could|would|will|are|is|r|u|you)\b[^.?!]{0,30}?"
    r"\b(?:decid|determin|know|classif|identif|work\s+out|tell|figure|judg|say|said|claim|conclud|prov|sure|"
    r"certain|confirm|verif|label|mark|treat|deriv|infer|categor|consider|assign|detect|recogni[sz]|justif)\w*"
    r"|\b(?:decid|determin|classif|identif)\w*\s+(?:on|from|by|based)\b"
    r"|\bhow\s+is\s+(?:it|this|the\s+channel|the\s+source)\b"
    r"|\bwhat\s+(?:decides|determines)\b|\bwhy\s+is\s+it\s+(?:csc|sro|citizen)\b"
    # "why are these SRO applications?", "what makes these SRO", "proof these are from SRO"
    r"|\bwhy\s+(?:are|is|do|does)\s+(?:th\w{2,4}|it|all|\d{4}/\S+)(?:\s|$)[^.?!]{0,40}?\b(?:sro|csc|citizen|sub[\s-]?registrar)\b"
    r"|\bwhat\s+makes?\s+(?:th\w{2,4}|it|\d{4}/\S+)(?:\s|$)[^.?!]{0,30}?\b(?:sro|csc|citizen|sub[\s-]?registrar)\b"
    r"|\b(?:proof|evidence|basis|reason|justification)\b[^.?!]{0,30}?\b(?:sro|csc|citizen|sub[\s-]?registrar)\b"
    # Tanglish: "ivai sro nu eppadi solreenga / theriyum / decide pannenga"
    r"|\beppadi\s+(?:solr\w*|sollr\w*|solring\w*|theriy\w*|therinj\w*|kandupidi\w*|mudivu\w*|decide\w*|confirm\w*)"
    r"|எப்படி\s*(?:தீர்மான|கண்டறி|தெரி|சொல்|முடிவு|உறுதி)|எதன்\s*அடிப்படை|எந்த\s*அடிப்படை|ஏன்\s+(?:இவை|இது)",
    re.IGNORECASE,
)
# The channels the question is deciding between.
_CHANNEL_NAMED_RE = re.compile(
    r"\bsro\b|\bsub[\s-]?registrar\b|\bcsc\b|\bcitizen\b"
    r"|\bchannel\b|\bsource\b|\bsubmission\s+(?:mode|route|channel)\b"
    r"|சார்-?பதிவாளர்|குடிமகன்|சேவை\s*மைய",
    re.IGNORECASE,
)


# The three submission channels, as words an officer uses to name them. Order
# is canonical so "CSC and SRO" and "SRO and CSC" produce the same topic.
_CHANNEL_DEFN_WORDS = (
    ("sub_registrar", re.compile(r"\bsro\b|\bsub[\s-]?registrar\b|சார்-?பதிவாளர்",
                                 re.IGNORECASE)),
    ("CSC", re.compile(r"\bcsc\b|\bcommon\s+service\s+cent(?:er|re)\b"
                       r"|சேவை\s*மைய|இ-?சேவை", re.IGNORECASE)),
    ("citizen", re.compile(r"\bcitizen\b|குடிமகன்", re.IGNORECASE)),
)


# "what are SRO applications", "what are my CSC applications" -- a request for
# the REGISTER, not for what the office is. `_SRO_ROLE_RE` claimed those on the
# words "what are" alone, so an officer asking to SEE their Sub-Registrar files
# was handed the definition of the Sub-Registrar Office and no list at all.
# A message naming applications / files is a listing and is left to the channel
# scope; the singular with an article ("what is an SRO application?") is still
# a definition.
_CHANNEL_LISTING_RE = re.compile(
    r"\b(?:applications?|apps?|files?|cases?)\b|விண்ணப்ப",
    re.IGNORECASE,
)
_CHANNEL_DEFN_SINGULAR_RE = re.compile(
    r"\b(?:a|an|one)\s+(?:sro|csc|citizen|sub[\s-]?registrar)\b",
    re.IGNORECASE,
)


def _asks_for_channel_list(msg: str) -> bool:
    """True when a channel question names the register, so it wants rows."""
    return bool(_CHANNEL_LISTING_RE.search(msg or "")
                and not _CHANNEL_DEFN_SINGULAR_RE.search(msg or ""))


def _channels_defined(msg: str) -> list:
    """Which submission channels a definition question names, canonical order."""
    return [name for name, rx in _CHANNEL_DEFN_WORDS if rx.search(msg or "")]


